async function DESCRIBE_OBJECT(obj, v$, level) {
  let str = false, av = 0;
  if ((level == 0) && (await apply(getProp(obj, P.DESCFCN), M_OBJDESC))) {
    return true;
  } else if ((level == 0) && ((!(hasFlag(obj, TOUCHBIT)) && (str = getProp(obj, P.FDESC))) || (str = getProp(obj, P.LDESC)))) {
    tell(S(str));
  } else if (level == 0) {
    tell("There is a ", D(obj), " here.");
  } else {
    tell(S(get(g.INDENTS, level)));
    tell("A ", D(obj));
    if (hasFlag(obj, WEARBIT)) {
      tell(" (being worn)");
    } else if (obj == SAFETY_LINE) {
      if (g.THIS_END && g.THAT_END) {
        tell(" (connecting the suit and a hook)");
      } else if (g.THIS_END) {
        tell(" (tied to the suit)");
      } else if (g.THAT_END) {
        tell(" (tied to a hook)");
      }
    }
  }
  if ((level == 0) && (av = loc(g.WINNER)) && hasFlag(av, VEHBIT)) {
    tell(" (outside the ", D(av), ")");
  }
  crlf();
  if ((await SEE_INSIDE$(obj)) && first(obj)) {
    return await PRINT_CONT(obj, v$, level);
  } else {
    return false;
  }
}

async function PRINT_CONT(obj, v$ = false, level = 0) {
  let y = 0, _1st$ = 0, av = 0, str = 0, pv$ = false, inv$ = false;
  if (!(y = first(obj))) {
    return true;
  }
  if ((av = loc(g.WINNER)) && hasFlag(av, VEHBIT)) {
  } else {
    av = false;
  }
  _1st$ = true;
  if (g.WINNER == obj || g.WINNER == loc(obj)) {
    inv$ = true;
  } else {
    loop1: for (;;) {
      if (!y) {
        !_1st$;
        break loop1;
      } else if (y == av) {
        pv$ = true;
      } else if (y == g.WINNER) {
      } else if (!(hasFlag(y, INVISIBLE)) && !(hasFlag(y, TOUCHBIT)) && (str = getProp(y, P.FDESC))) {
        if (!(hasFlag(y, NDESCBIT))) {
          tell(S(str), "\n");
        }
        if ((await SEE_INSIDE$(y)) && !(getProp(loc(y), P.DESCFCN)) && first(y)) {
          await PRINT_CONT(y, v$, 0);
        }
      }
      y = next(y);
    }
  }
  y = first(obj);
  for (;;) {
    if (!y) {
      if (pv$ && av && first(av)) {
        await PRINT_CONT(av, v$, level);
      }
      return !_1st$;
    } else if (y == av || y == ADVENTURER) {
    } else if (!(hasFlag(y, INVISIBLE)) && (inv$ || hasFlag(y, TOUCHBIT) || !(getProp(y, P.FDESC)))) {
      if (!(hasFlag(y, NDESCBIT))) {
        if (_1st$) {
          if (await FIRSTER(obj, level)) {
            if (level < 0) {
              level = 0;
            }
          }
          level = 1 + level;
          _1st$ = false;
        }
        await DESCRIBE_OBJECT(y, v$, level);
      } else if (first(y) && (await SEE_INSIDE$(y))) {
        await PRINT_CONT(y, v$, level);
      }
    }
    y = next(y);
  }
}

