async function JIGS_UP(desc, player$ = false) {
  tell(S(desc), "\n");
  for (;;) {
    await SCORE_UPD(-10);
    tell(" \n    ****  You have died  **** \n\n");
    g.DEATHS = g.DEATHS + 1;
    if (g.DEATHS == 4) {
      if (g.DOCKED$) {
        tell("The expressionless voice seems despairing. \"Four failures. They would not be pleased. Such promising candidates, too. If only...\" The voice trails off into background hiss. Nothing more happens, ever.\n");
      } else {
        tell("This time, you aren't given another chance.\n");
      }
      await FINISH();
    } else if (g.POISON_COUNT > 3) {
      tell("An expressionless voice seems to be trying to express outrage, but not successfully. \"The candidate has not made the necessary repairs in time. This is a disaster. All are now dead, and repairs are not possible. They would not approve. This area will be marked, that is certain.\" Everything fades to black, and silence reigns.\n");
      await FINISH();
    }
    await RANDOMIZE_OBJECTS();
    if (hasFlag(RED_THREE, TOUCHBIT)) {
      move(g.WINNER, RED_THREE);
    } else {
      g.IN_ARTIFACT$ = false;
      clearFlag(AIRLOCK_OUTER, OPENBIT);
      clearFlag(AIRLOCK_INNER, OPENBIT);
      move(g.WINNER, SPACESHIP_BRIDGE);
      move(SPACESUIT, SPACESHIP_STORES);
    }
    if (g.DOCKED$) {
      tell("You hear, if that is the right word, an expressionless voice. It seems to be inside your head. \"This is not promising. The candidate does not deserve another chance, but the instructions are explicit. There are not even any more docking ports. They would be disappointed if they knew.\" You wake to a brief glimpse of a pallet (on which you are lying) surrounded by metallic threads. The whole apparatus begins to vibrate and you feel very dizzy. As you lose consciousness, you realize that you can't see the rest of your body. There is a feeling of dislocation, and then...\n");
    } else {
      tell("You wake to find yourself alive, on board the \"Starcross.\" It appears you have been given another chance.\n");
    }
    g.LIT = true;
    clearFlag(SPACESUIT, WEARBIT);
    g.SUIT_ON$ = false;
    g.THIS_END = false;
    g.THAT_END = false;
    g.P_CONT = false;
    g.COUNTDOWN = false;
    g.R_VALUE = 0;
    g.PHI_VALUE = 0;
    g.THETA_VALUE = 0;
    g.LOST = false;
    g.GIVE_UP = false;
    await KILL_INTERRUPTS();
    return M_FATAL;
  }
}

