async function ITAKE(vb = true) {
  let cnt = 0, obj = 0, wloc = 0;
  let $1;
  if (!(hasFlag(g.PRSO, TAKEBIT))) {
    if (vb) {
      $1 = await PICK_ONE(g.YUKS);
      tell(S($1));
      tell("\n");
    }
    return false;
  } else if (!(loc(loc(g.PRSO)) == g.WINNER) && (((await WEIGHT(g.PRSO)) + (await WEIGHT(g.WINNER))) > g.LOAD_ALLOWED)) {
    if (vb) {
      tell("Your load is too heavy.\n");
    }
    return M_FATAL;
  } else if (((cnt = await CCOUNT(g.WINNER)) > g.FUMBLE_NUMBER) && ((cnt * g.FUMBLE_PROB) > random(100))) {
    obj = first(g.WINNER);
    obj = next(obj);
    tell("Oh, no. The ", D(obj), " slips from your arms while taking the ", D(g.PRSO), " and both tumble to the floor.\n");
    wloc = loc(g.WINNER);
    if (g.PRSO == g.UNDER_GLOBE) {
      g.UNDER_GLOBE = false;
      clearFlag(g.PRSO, NDESCBIT);
    }
    if (hasFlag(wloc, RMUNGBIT) || (wloc == UP_A_TREE || wloc == TREETOP_ROOM || wloc == DRIVE_BUBBLE_ENTRANCE) || (wloc == CONTROL_BUBBLE_ENTRANCE)) {
      await PERFORM(V.DROP, obj);
      move(g.PRSO, g.WINNER);
      await PERFORM(V.DROP, g.PRSO);
    } else {
      move(obj, wloc);
      move(g.PRSO, wloc);
    }
    return M_FATAL;
  } else {
    move(g.PRSO, g.WINNER);
    clearFlag(g.PRSO, NDESCBIT);
    await SCORE_OBJ(g.PRSO);
    setFlag(g.PRSO, TOUCHBIT);
    return true;
  }
}

