async function PRINT_CONTENTS(obj) {
  let f = 0, n_ = 0, _1st$ = true;
  if (f = first(obj)) {
    for (;;) {
      n_ = next(f);
      if (_1st$) {
        _1st$ = false;
      } else {
        tell(", ");
        if (!n_) {
          tell("and ");
        }
      }
      tell("a ", D(f));
      f = n_;
      if (!f) {
        return true;
      }
    }
  } else {
    return false;
  }
}

