async function ROB(who, where = false, hide$ = false) {
  let n_ = 0, x = 0, robbed$ = false;
  x = first(who);
  for (;;) {
    if (!x) {
      return robbed$;
    }
    n_ = next(x);
    if (await RIPOFF(x, where)) {
      if (hide$) {
        setFlag(x, NDESCBIT);
      }
      robbed$ = x;
    }
    x = n_;
  }
}

async function RIPOFF(x, where) {
  if ((x == BLUE_KEY) && (loc(BLUE_KEY) == FORCE_FIELD_1)) {
    return false;
  } else if (!(loc(x) == where) && !(hasFlag(x, INVISIBLE)) && hasFlag(x, TOUCHBIT) && hasFlag(x, TAKEBIT)) {
    if (x == g.UNDER_GLOBE) {
      clearFlag(x, NDESCBIT);
      g.UNDER_GLOBE = false;
    }
    if (x == RED_DISK || x == BLUE_DISK) {
      await DISK_SWITCH(x, false);
    }
    if ((x == SPACESUIT || x == SAFETY_LINE) && g.THAT_END) {
      return true;
    }
    if (where) {
      move(x, where);
    } else {
      remove(x);
    }
    return true;
  } else {
    return false;
  }
}

