async function COURSE_SET() {
  if (g.R_VALUE && g.THETA_VALUE && g.PHI_VALUE) {
    g.GOT_INSTRUCTIONS = true;
    g.DESTINATION = false;
    g.LOST = false;
    tell("\" Lights blink furiously for a moment. The computer speaks: ");
    g.GIVE_UP = await FIND_DESTINATION(g.KNOWN_LOCS, g.KNOWNS);
    if (g.GIVE_UP) {
      tell("\"Navigational program for ", D(g.GIVE_UP), " is ready. Giving up, huh? Figures, just when we get a good strike. ");
    } else if ((g.DESTINATION = await FIND_DESTINATION(g.MASS_LOCS, g.MASSES)) && (g.DESTINATION == g.MASS)) {
      tell("\"Sequence for intercept of mass concentration is programmed and ready. ");
    } else {
      g.LOST = true;
      tell("\"I know my instruments aren't as good as the mass detector, but I see nothing at that location. Well, if you say so. ");
    }
    tell("Please confirm new navigational program. I'm waiting...\"\n");
    return true;
  } else {
    tell(" Waiting for additional values.\"\n");
    return true;
  }
}

async function FIND_DESTINATION(x, m) {
  let c_ = 0, n_ = get(x, 0);
  for (;;) {
    c_ = c_ + 1;
    if (eq(get(x, 1), g.R_VALUE) && eq(get(x, 2), g.THETA_VALUE) && eq(get(x, 3), g.PHI_VALUE)) {
      return get(m, c_);
    }
    if (c_ == n_) {
      return false;
    }
    x = x + 6;
  }
}

async function KNOWN_COURSE(d_, set$) {
  let x = 0, n_ = 0, c_ = 0;
  x = g.KNOWN_LOCS;
  n_ = get(x, 0);
  for (;;) {
    c_ = c_ + 1;
    if (eq(get(g.KNOWNS, c_), d_)) {
      if (set$) {
        g.R_VALUE = get(x, 1);
        g.THETA_VALUE = get(x, 2);
        g.PHI_VALUE = get(x, 3);
        return d_;
      } else {
        return x;
      }
    }
    if (c_ == n_) {
      return false;
    }
    x = x + 6;
  }
}

async function REPORT_LOCATION(m, ml, n_) {
  tell("\"Coordinates for ", D(m), ": R is ", N(get(ml, n_)), ", theta is ", N(get(ml, n_ + 1)), ", phi is ", N(get(ml, n_ + 2)), ".\"\n");
  return true;
}

async function CONTROLS_FCN() {
  if (g.HERE == THRONE_ROOM) {
    if (isVerb(V.EXAMINE)) {
      return await AS_ADVERTISED();
    } else {
      tell("The controls look in no way operational.\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("This is a standard control panel for this class of single-passenger mining ship. Most controls are for emergencies only, as the Starcross is normally controlled by verbal instructions to the computer.");
    if (!(loc(COMPUTER) == g.HERE)) {
      tell(" This set of controls is non-functional.");
    }
    crlf();
    return true;
  } else if (isVerb(V.RUB, V.SET, V.LAMP_ON, V.LAMP_OFF, V.PLAY)) {
    if (!(loc(COMPUTER) == g.HERE)) {
      tell("The controls are no longer functional.\n");
      return true;
    } else if (g.COMPUTER_ON) {
      if (g.GOT_INSTRUCTIONS) {
        tell("As you reach for the controls, the computer blares: \"Warning! Warning! Course is set! Remember what happened last time you played with the controls in mid-course...\"\n");
        return true;
      } else {
        tell("The computer's voice intrudes. \"Do you really want to touch the controls just now? Not to impugn your piloting ability, but shouldn't I execute any course corrections? I'm very good at it, you know.\"\n");
        return true;
      }
    } else {
      g.COMPUTER_ON = true;
      tell("The computer comes on and chides, \"Manual operation when the ship's computer is functional is not recommended. Ship's controls are not currently enabled.\"\n");
      return true;
    }
  } else {
    return false;
  }
}

