async function FIND_IN(where, what) {
  let w_ = 0;
  w_ = first(where);
  if (!w_) {
    return false;
  }
  for (;;) {
    if (hasFlag(w_, what)) {
      return w_;
    } else if (!(w_ = next(w_))) {
      return false;
    }
  }
}

async function FIND_TARGET(target) {
  let p_ = 0, tx = 0, l = 0, room = 0;
  if (loc(target) == g.HERE) {
    return g.HERE;
  } else {
    p_ = 0;
    for (;;) {
      if ((p_ = nextProp(g.HERE, p_)) == 0) {
        return false;
      } else if (!(p_ < LOW_DIRECTION)) {
        tx = getPropAddr(g.HERE, p_);
        l = propSize(tx);
        if ((l == UEXIT) || ((l == CEXIT) && globalValue(getb(tx, CEXITFLAG))) || ((l == DEXIT) && hasFlag(getb(tx, DEXITOBJ), OPENBIT))) {
          room = getb(tx, 0);
          if (loc(target) == room) {
            return room;
          }
        }
      }
    }
  }
}

async function COMPUTER_FCN() {
  let n_ = 0;
  if (g.WINNER == COMPUTER) {
    if (!g.COMPUTER_ON) {
      g.COMPUTER_ON = true;
      tell("The computer turns itself on.\n");
    }
    if (isVerb(V.WALK_TO) || (isVerb(V.SET) && (g.PRSO == COURSE))) {
      if (isVerb(V.WALK_TO)) {
        g.PRSI = g.PRSO;
      }
      if (g.DOCKED$) {
        tell(S(g.ROPES_OFF), "\n");
        return true;
      } else if (g.ORBIT_MATCHED) {
        tell("\"We just got here! I think we should look around first!\"\n");
        return true;
      } else if (g.COUNTDOWN) {
        tell(S(g.BURN_COMING), "\n");
        return true;
      } else if (g.COURSE_SELECTED) {
        tell(S(g.IN_TRANSIT), "\n");
        return true;
      }
      if (await KNOWN_COURSE(g.PRSI, true)) {
        tell("\"Course being set for ", D(g.PRSI), ".");
        return await COURSE_SET();
      } else {
        tell("The computer sounds surly. \"I told you to buy those additional I/O options. You know as well as I do that I can't talk to that stupid mass detector, so you'll just have to tell me the coordinates from its output. Maybe next time you'll listen.\"\n");
        return true;
      }
    } else if (isVerb(V.R, V.THETA, V.PHI)) {
      if (g.VIEW_COUNT > 0) {
        tell("\"We just got here. You wouldn't be scared, would you?\"\n");
        return true;
      } else if (g.TRIP_COUNT > 0) {
        tell(S(g.IN_TRANSIT), "\n");
        return true;
      } else if (g.DOCKED$) {
        tell(S(g.ROPES_OFF), "\n");
        return true;
      } else if (g.COUNTDOWN) {
        tell(S(g.BURN_COMING), "\n");
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.NO)) {
      g.GOT_INSTRUCTIONS = false;
      g.R_VALUE = false;
      g.THETA_VALUE = false;
      g.PHI_VALUE = false;
      g.GIVE_UP = false;
      g.LOST = false;
      tell("\"Okay.\"\n");
      return true;
    } else if (isVerb(V.YES)) {
      if (g.PRSO && !(g.PRSO == COURSE)) {
        tell("\"You can't confirm that!\"\n");
        return true;
      } else if (g.GOT_INSTRUCTIONS) {
        g.GOT_INSTRUCTIONS = false;
        g.COUNTDOWN = true;
        enable(await QUEUE(I_BURN.id, 3));
        tell("\"Thank you. New navigational program will initiate in fifteen seconds. There will be a course correction burn of ", N(30 + random(30)), " seconds duration. I advise you to fasten your seat belt.\"\n");
        return true;
      } else {
        tell("\"No pending program. Confirmation ignored.\"\n");
        return true;
      }
    } else if (isVerb(V.LAND)) {
      if (g.PRSO) {
        if (g.PRSO == ARTIFACT) {
          await PERFORM(V.LAND);
          return true;
        } else {
          await PERFORM(V.SET, COURSE, g.PRSO);
          return true;
        }
      } else if (g.DOCKED$) {
        tell("\"Error. I am already landed. Program cancelled.\"\n");
        return true;
      } else if (g.VIEW_COUNT > 0) {
        tell("\"Working...working...program aborted. The object is spinning too fast for a safe landing. I can maintain current synchronized course indefinitely.\"\n");
        return true;
      } else {
        tell("\"Program cancelled. There is nothing nearby to land on.\"\n");
        return true;
      }
    } else if (isVerb(V.EXAMINE)) {
      if (g.PRSO == MISSION_STATUS || g.PRSO == COURSE) {
        await PERFORM(V.REPORT, MISSION_STATUS);
        return true;
      } else {
        tell("\"Your eyes are better than mine for that.\"\n");
        return true;
      }
    } else if (isVerb(V.HELLO)) {
      tell("\"Hello, astronaut.\"\n");
      return true;
    } else if (isVerb(V.FIND)) {
      if (g.PRSO == ME) {
        await PERFORM(V.REPORT, MISSION_STATUS);
        return true;
      } else if (n_ = await KNOWN_COURSE(g.PRSO, false)) {
        return await REPORT_LOCATION(g.PRSO, n_, 1);
      } else {
        tell("\"I don't know where that is.\"\n");
        return true;
      }
    } else if ((isVerb(V.REPORT) && (g.PRSO == MISSION_STATUS)) || (isVerb(V.SGIVE, V.GIVE) && (MISSION_STATUS == g.PRSO || MISSION_STATUS == g.PRSI))) {
      if (g.LOST) {
        tell("\"We're on our way somewhere unpromising, that's all I can tell you.\"\n");
        return true;
      } else if (g.GIVE_UP) {
        tell("\"You've given up and are heading for ", D(g.GIVE_UP), ", remember?\"\n");
        return true;
      } else if (g.DOCKED$) {
        tell("\"We've docked with this odd object. I think those tentacles may have broken something; I don't feel too well.\"\n");
        return true;
      } else if (g.VIEW_COUNT > 0) {
        tell("\"We're on a parallel course with a strange, rotating artifact.\"\n");
        return true;
      } else if (g.TRIP_COUNT > 0) {
        tell("\"We're heading towards that newly reported unknown mass.");
        if (g.TRIP_COUNT > 2) {
          tell(" We are being scanned by radiation emanating from that mass.");
        }
        tell("\"\n");
        return true;
      } else if (g.COUNTDOWN) {
        tell("\"Counting down to course correction.\"\n");
        return true;
      } else if (g.GOT_INSTRUCTIONS) {
        tell("\"Waiting for confirmation of new course.\"\n");
        return true;
      } else if ((g.R_VALUE == 0) && (g.THETA_VALUE == 0) && (g.PHI_VALUE == 0)) {
        tell("\"The mass detector has reported discovery of a new mass concentration. Other than that, things have been pretty dull around here.\"\n");
        return true;
      } else {
        tell("\"We have a partially specified new course:");
        if (!(g.R_VALUE == 0)) {
          tell(" R is ", N(g.R_VALUE), ".");
        }
        if (!(g.THETA_VALUE == 0)) {
          tell(" Theta is ", N(g.THETA_VALUE), ".");
        }
        if (!(g.PHI_VALUE == 0)) {
          tell(" Phi is ", N(g.PHI_VALUE), ".\"");
        }
        return crlf();
      }
    } else if (isVerb(V.LAMP_OFF) && (g.PRSO == ALARM)) {
      if (!g.ALARM$) {
        tell("\"It's not on...\"\n");
        return true;
      } else {
        tell("\"And about time...\"\n");
        g.ALARM$ = false;
        return await QUEUE(I_ALARM.id, 0);
      }
    } else if (isVerb(V.WAIT)) {
      tell("\"I can wait quite easily. Probably more easily than you.\"\n");
      return true;
    } else if (isVerb(V.KILL, V.ATTACK, V.MUNG) && (g.PRSO == ME)) {
      tell("\"That is not among my capabilities. Sigh.\"\n");
      return true;
    } else if (25 > random(100)) {
      tell("\"That is not among my capabilities. Perhaps if you were to invest in a few upgrades I could do some of these things, but no...\"\n");
      return true;
    } else {
      tell("\"I'm only a navigational computer. That is not one of my functions.\"\n");
      return true;
    }
  } else if (isVerb(V.HELLO)) {
    tell("\"I haven't the patience for small talk.\"\n");
    return true;
  } else if (isVerb(V.LAMP_ON)) {
    if (g.COMPUTER_ON) {
      return (await ALREADY("on", COMPUTER));
    } else {
      g.COMPUTER_ON = true;
      tell("The computer comes on.\n");
      return true;
    }
  } else if (isVerb(V.LAMP_OFF)) {
    if (g.COMPUTER_ON) {
      g.COMPUTER_ON = false;
      tell("\"If you insist, but my programming impels me to come back on if anything important happens.\"\n");
      return true;
    } else {
      return (await ALREADY("off", COMPUTER));
    }
  } else if (isVerb(V.GIVE)) {
    tell("\"I might be able to take that if you had bought the extensors I asked for, but no...\"\n");
    return true;
  } else if (isVerb(V.TELL) && !g.P_CONT) {
    tell("\"Yes?\"\n");
    return true;
  } else {
    return false;
  }
}

async function I_BURN() {
  g.COUNTDOWN = false;
  await ROB(DEEP_SPACE);
  tell("The ship's thrusters spin it into a proper attitude, and then the engines begin their course correction burn. There are significant G's and not a little vibration.\n");
  if (g.SEAT_BELT$) {
    tell("Fortunately, you are securely belted in.\n");
    g.COURSE_SELECTED = true;
    return enable(await QUEUE(I_TRIP.id, 3));
  } else {
    g.R_VALUE = 0;
    g.THETA_VALUE = 0;
    g.PHI_VALUE = 0;
    g.GOT_INSTRUCTIONS = false;
    g.WINNER = ADVENTURER;
    return (await JIGS_UP("The G forces drive you against the rear bulkhead (which is unpadded, of course). You are crushed to death."));
  }
}

async function I_TRIP() {
  tell("Time passes as you journey towards your destination.\n");
  g.TRIP_COUNT = g.TRIP_COUNT + 1;
  if (g.GIVE_UP) {
    tell("\nYou arrive at ", D(g.GIVE_UP), " safe and sound. It would be tedious to continue, as ", D(g.GIVE_UP), " has no prospects as a locale for quantum black holes, so this is the end.\n");
    await FINISH();
    return true;
  }
  if (g.HERE == SPACESHIP_BRIDGE || g.HERE == SPACESHIP_AIRLOCK || g.HERE == DEEP_SPACE) {
    if (g.LOST || !(g.DESTINATION == g.MASS)) {
      tell("There is nothing interesting visible ahead.\n");
    } else {
      tell(S(get(g.TRIP_DESCS, g.TRIP_COUNT)), "\n");
    }
  }
  if (g.TRIP_COUNT == 5) {
    if (g.LOST) {
      tell("You have reached your destination. The computer speaks: \"There's nothing here, as I predicted. You never listen do you? This trip is over; See if I'll ever work with you again...\"\n\n\n");
      return await FINISH();
    } else if (g.DESTINATION == g.MASS) {
      tell("There is a brief burn as the ship matches course with the artifact. You are hanging in space about half a kilometer away from the waist of the object. The Starcross's engines shut down. The computer speaks: \"Program completed. We are being scanned by low level radiation. Awaiting instructions.\"\n");
      g.VIEW_COUNT = 1;
      enable(await QUEUE(I_VIEW.id, 2));
      return g.ORBIT_MATCHED = true;
    } else {
      tell("Ahead is a nondescript nickel-iron asteroid, rather a small one too. Obviously, you have picked the wrong destination.\n\n\n");
      return await FINISH();
    }
  } else {
    if (!g.LOST && (g.DESTINATION == g.MASS)) {
      if (g.TRIP_COUNT == 3) {
        tell("The computer says, \"Telescopic observations reveal the object ahead to be extremely regular in shape. This is not your usual asteroid.\"\n");
      } else if (g.TRIP_COUNT == 4) {
        tell("The computer remarks: \"I detect low-level scanning taking place. The radiation is not dangerous. I think we may be getting into something more than we expected here.\"\n");
      }
    }
    return enable(await QUEUE(I_TRIP.id, 3));
  }
}

async function I_VIEW() {
  if (g.HERE == SPACESHIP_BRIDGE || g.HERE == SPACESHIP_AIRLOCK) {
    tell("As the object rotates below, the features of a different area become visible through the viewport.\n");
    tell(S(get(g.VIEW_TABLE, mod(g.VIEW_COUNT - 1, 4))), "\n");
  }
  g.VIEW_COUNT = g.VIEW_COUNT + 1;
  if (g.VIEW_COUNT == 5) {
    return await TENTACLE_APPEARS();
  } else {
    return enable(await QUEUE(I_VIEW.id, 2));
  }
}

async function TENTACLE_APPEARS() {
  enable(await QUEUE(I_MOUSE.id, 1));
  enable(await QUEUE(I_BAD_AIR.id, 75 + random(50)));
  tell("Suddenly an odd protrusion near the red dome splits open and a huge articulated metal tentacle issues from it at great speed.");
  if (g.HERE == DEEP_SPACE) {
    crlf();
    (await JIGS_UP("The tentacle grabs the Starcross, spinning you off into the depths of space!"));
  } else if (g.HERE == SPACESHIP_BRIDGE || g.HERE == SPACESHIP_AIRLOCK) {
    tell(" It approaches the ship and delicately wraps itself around the hull.");
    if (g.SEAT_BELT$) {
      tell(" You are slammed against your seat");
    } else {
      tell(" You are smashed against the bulkhead");
    }
    tell(" as the tentacle accelerates the Starcross to the artifact's speed of rotation. Inexorably, your ship is drawn toward the dome. When you are a few tens of meters away, three smaller tentacles issue forth and grapple the ship solidly to the surface of the artifact. The large tentacle retreats into its housing, which closes.\n");
    if (g.SEAT_BELT$) {
      tell("\nYou are disoriented: now that you are attached to the artifact, which is rotating, \"up\" and \"down\" have taken on new meanings. Your sense of balance tells you that your ship is clinging to the underside of some enormous object, and if you aren't careful you will fall! \"Up\" now refers to the center of the object, \"down\" to the immensities of space.\n");
    } else {
      (await JIGS_UP("Unfortunately, the accelerations involved were tremendous, and being smashed into the walls didn't help your condition either."));
    }
  } else {
    (await JIGS_UP("Something has grabbed the ship! You are slammed against the bulkhead! After a great deal of buffeting, there is a metallic clang and the ship is at rest, but unfortunately, so are you."));
  }
  return g.DOCKED$ = true;
}

async function TAPE_FCN() {
  let $1;
  if (isVerb(V.TAKE)) {
    if (loc(TAPE_PLAYER) == SPIDER) {
      tell("The spider refuses to part with it.\n");
      return true;
    } else {
      return false;
    }
  } else if (!(loc(TAPE_PLAYER) == g.WINNER)) {
    return await DONT_HAVE(TAPE_PLAYER);
  } else if (isVerb(V.LAMP_ON)) {
    if (g.TAPE_ON) {
      return (await ALREADY("on", TAPE_PLAYER));
    } else {
      g.TAPE_ON = true;
      tell("The ", D(g.PRSO), " comes on.\n");
      return true;
    }
  } else if (isVerb(V.LAMP_OFF)) {
    if (g.TAPE_ON) {
      g.TAPE_ON = false;
      tell("The ", D(g.PRSO), " is now off.\n");
      return true;
    } else {
      return (await ALREADY("off", TAPE_PLAYER));
    }
  } else if (isVerb(V.PLAY, V.WEAR)) {
    if (!g.TAPE_ON) {
      tell("First, you must turn on the tape player.\n");
      return true;
    } else {
      tell("The player picks a recently referenced selection: ");
      $1 = await PICK_ONE(g.TAPES);
      tell(S($1));
      tell("\n");
      return true;
    }
  } else if (isVerb(V.LISTEN)) {
    if (g.TAPE_ON) {
      tell("The tape player continues with the previous selection.\n");
      return true;
    } else {
      tell("The player isn't on.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function MOUSE_CONT() {
  if (isVerb(V.TAKE)) {
    tell("The maintenance mouse buzzes briefly, then rotates its \"ears\" in your direction as you take the ", D(g.PRSO), ". It seems profoundly puzzled at your behavior.\n");
    return false;
  } else {
    return false;
  }
}

async function MOUSE_GOODIES() {
  if (first(MOUSE)) {
    tell(" It has already collected ");
    await PRINT_CONTENTS(MOUSE);
    tell(".");
  }
  return true;
}

async function MOUSE_FCN(rarg = false) {
  if (rarg == M_OBJDESC) {
    if (loc(MOUSE) == GARAGE) {
      tell("There is a maintenance mouse here.");
    } else if (g.SEEN_MOUSE$) {
      tell("There is a maintenance mouse here, cheerfully scouring the area for garbage.");
      await MOUSE_GOODIES();
    } else {
      g.SEEN_MOUSE$ = true;
      tell("A small metal contraption about a meter long and half a meter high enters the room.", S(g.LONG_MOUSE));
    }
    return crlf();
  } else if (!(loc(MOUSE) == g.HERE) && ((GLOBAL_MOUSE == g.PRSO || GLOBAL_MOUSE == g.PRSI) || (MOUSE == g.PRSO || MOUSE == g.PRSI))) {
    if (isVerb(V.FOLLOW)) {
      if (!g.LIT) {
        tell("It's too dark to follow the mouse.\n");
        return true;
      } else if (g.GARAGED$) {
        tell("You can't go through the hole.\n");
        return true;
      } else if (g.MFOLLOW) {
        await DO_WALK(g.MFOLLOW);
        return true;
      } else {
        tell("You've lost him.\n");
        return true;
      }
    } else {
      tell("There is no mouse here.\n");
      return true;
    }
  } else if (isVerb(V.FOLLOW)) {
    tell("He's right here!\n");
    return true;
  } else if (isVerb(V.ZAP) && (await CAN_ZAP$())) {
    disable(await INT(I_MOUSE.id));
    remove(MOUSE);
    tell("The mouse is obliterated, squealing piteously.\n");
    return true;
  } else if (isVerb(V.MUNG)) {
    tell("The maintenance mouse is unscathed.\n");
    return true;
  } else if (isVerb(V.EMPTY)) {
    if (await ROB(MOUSE, g.WINNER)) {
      tell("You get some booty!\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    if (isVerb(V.EXAMINE)) {
      tell("The maintenance mouse is a boxy machine with a large receptacle on top in which garbage it collects can be stored. It is buzzing around cleaning the area, diligently polishing the floor, and waving its \"ears\" (small dish antennae) about.\n");
    }
    if (first(MOUSE)) {
      tell("The receptacle on the mouse's back contains: ");
      await PRINT_CONTENTS(MOUSE);
      tell(".\n");
      return true;
    } else {
      tell("The receptacle is empty.\n");
      return true;
    }
  } else if (isVerb(V.LOOK_UNDER)) {
    tell("There is no dirt there.\n");
    return true;
  } else if (isVerb(V.BOARD)) {
    tell("The mouse buzzes piteously from the overload until you get back off. It only wants to collect small pieces of debris.\n");
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    tell("The mouse has no lid, just an open receptacle on its back.\n");
    return true;
  } else {
    return false;
  }
}

async function OUT_OF_HOLE() {
  if (g.SEEN_MOUSE$ && g.LIT) {
    tell("A maintenance mouse", S(g.HOLE_SHUTS), ".\n");
  } else {
    g.SEEN_MOUSE$ = true;
    tell("A small metal contraption", S(g.HOLE_SHUTS), ". The device stops in its tracks and buzzes briefly, allowing you a closer look.", S(g.LONG_MOUSE), "\n");
  }
  return true;
}

async function I_MOUSE() {
  let oldm = loc(MOUSE), here$ = (loc(MOUSE) == g.HERE), robbed$ = 0;
  enable(await QUEUE(I_MOUSE.id, 2));
  remove(MOUSE_HOLE);
  g.GARAGED$ = false;
  robbed$ = await ROB(loc(MOUSE), MOUSE);
  if (robbed$ && here$ && !(loc(MOUSE) == GARAGE)) {
    if (g.LIT) {
      tell("The maintenance mouse, buzzing happily, picks up some refuse.\n");
    } else {
      tell("You hear a cheerful buzzing nearby.\n");
    }
  }
  if (loc(MOUSE) == GARAGE) {
    if (first(MOUSE)) {
      await ROB(MOUSE, TRASH_BIN);
      if (loc(BLUE_DISK) == TRASH_BIN) {
        move(BLUE_DISK, GARAGE);
      }
      if (loc(RED_DISK) == TRASH_BIN) {
        move(RED_DISK, GARAGE);
      }
      if (here$ && g.LIT) {
        tell("The mouse rolls up to the trash bin and dumps some stuff into it.\n");
      }
    }
    if (40 > random(100)) {
      if (here$ && g.LIT) {
        tell("The mouse leaves as unobtrusively as it arrived.\n");
      }
      move(MOUSE, g.MOUSE_LOC);
      if (g.MOUSE_LOC == g.HERE) {
        move(MOUSE_HOLE, g.HERE);
        await OUT_OF_HOLE();
      }
    }
  } else if (here$ && (30 > random(100))) {
    if (g.LIT) {
      tell("The maintenance mouse sits in the middle of the room, buzzing contentedly.\n");
    } else {
      tell("There is buzzing nearby.\n");
    }
  } else if (first(MOUSE) && (15 > random(100))) {
    g.MOUSE_LOC = loc(MOUSE);
    move(MOUSE, GARAGE);
    g.GARAGED$ = true;
    if (g.HERE == GARAGE) {
      if (g.LIT) {
        tell("A maintenance mouse enters the garage, preparing to dump a load of trash.\n");
      }
    } else if (here$) {
      move(MOUSE_HOLE, here$);
      if (g.LIT) {
        tell("The mouse disappears into a heretofore unnoticed hole in the wall, which closes and becomes nearly invisible.\n");
      }
    }
  } else {
    await MOVE_MOUSE();
    robbed$ = await ROB(loc(MOUSE), MOUSE);
    if (!(loc(MOUSE) == g.HERE)) {
      if (here$ && g.LIT) {
        tell("The maintenance mouse glides happily away, looking for new dirt to conquer.\n");
        return true;
      }
    } else if (!g.SEEN_MOUSE$ && g.LIT) {
      await MOUSE_FCN(M_OBJDESC);
    } else if (g.LIT) {
      tell("A maintenance mouse buzzes into the room, intent on trash.");
      await MOUSE_GOODIES();
      crlf();
    }
    here$ = loc(MOUSE) == g.HERE;
    if (!g.LIT) {
    } else if (robbed$) {
      if (here$) {
        tell("The mouse collects some discarded items.\n");
      }
    } else if (here$) {
      tell("The mouse is diligently cleaning the floor and looking for garbage.\n");
    }
  }
  return loc(MOUSE) == g.HERE;
}

async function MOVE_MOUSE() {
  let h = loc(MOUSE), p_ = 0, tx = 0, l = 0, d_ = false;
  for (;;) {
    if ((p_ = nextProp(h, p_)) < LOW_DIRECTION) {
      if (d_) {
        if (d_ == UP_A_TREE) {
          if (loc(MOUSE) == g.HERE) {
            tell("The mouse tries to climb a tree, but fails dismally.\n");
          }
          return false;
        } else if (d_ == MAZE) {
          if (loc(MOUSE) == g.HERE) {
            tell("The mouse tries to enter the warren, but is prodded away by several aliens.\n");
          }
          return false;
        } else {
          move(MOUSE, d_);
        }
      }
      return true;
    } else {
      tx = getPropAddr(h, p_);
      l = propSize(tx);
      if ((l == UEXIT) || ((l == CEXIT) && globalValue(getb(tx, CEXITFLAG)))) {
        if (!d_ || (50 > random(100))) {
          if (loc(MOUSE) == g.HERE) {
            g.MFOLLOW = p_;
          }
          d_ = getb(tx, REXIT);
        }
      }
    }
  }
}

