async function TRASH_BIN_FCN() {
  if (isVerb(V.LOOK_INSIDE, V.EXAMINE)) {
    tell("The bin is filled with all sorts of flotsam and jetsam. Bones, clothing, and broken spears are just some of the items visible on the top layer.");
    if (first(TRASH_BIN)) {
      tell(" The bin also contains: ");
      await PRINT_CONTENTS(TRASH_BIN);
      tell(".");
    }
    return crlf();
  } else if (isVerb(V.SHAKE)) {
    tell("The bin is solidly affixed to the floor.\n");
    return true;
  } else if (isVerb(V.REACH, V.EMPTY)) {
    tell("There's a lot of stuff inside the bin.\n");
    return true;
  } else if (isVerb(V.SEARCH, V.DIG, V.THROUGH)) {
    if (hasFlag(GREEN_KEY, TOUCHBIT)) {
      tell("You find nothing else of interest.\n");
      return true;
    } else if (g.TRASH_COUNT == 0) {
      tell("You have searched through part of the bin, but have found nothing of interest.\n");
      return g.TRASH_COUNT = 25;
    } else if (g.TRASH_COUNT > random(100)) {
      move(GREEN_KEY, TRASH_BIN);
      setFlag(GREEN_KEY, TOUCHBIT);
      await THIS_IS_IT(GREEN_KEY);
      tell("Ahah, there's something! It appears to be a green crystal rod.\n");
      return true;
    } else {
      g.TRASH_COUNT = g.TRASH_COUNT + 25;
      tell("You continue sifting through the junk; nothing of interest turns up.\n");
      return true;
    }
  } else {
    return false;
  }
}

