async function AIRLOCK_DOORS_FCN() {
  let dir = 0;
  if (isVerb(V.THROUGH)) {
    if (g.HERE == SPACESHIP_AIRLOCK) {
      if (g.PRSO == AIRLOCK_INNER) {
        dir = P.WEST;
      } else {
        dir = P.UP;
      }
    } else if (g.PRSO == AIRLOCK_INNER) {
      dir = P.EAST;
    } else {
      dir = P.DOWN;
    }
    await DO_WALK(dir);
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    if (g.PRSO && g.PRSI && (g.PRSO == AIRLOCK)) {
      await PERFORM(g.PRSA, g.PRSI);
      return true;
    } else if (g.PRSO == AIRLOCK_INNER) {
      if (isVerb(V.OPEN)) {
        if (loc(g.WINNER) == COUCH) {
          tell("You'll have to get out of the couch first.\n");
          return true;
        } else if (hasFlag(g.PRSO, OPENBIT)) {
          return (await ALREADY("open"));
        } else if (hasFlag(AIRLOCK_OUTER, OPENBIT)) {
          tell("Fortunately the safety interlock prevents you from evacuating the spaceship by opening both doors of the airlock at once.\n");
          return true;
        } else {
          return await DOOR_OPENS();
        }
      } else if (loc(g.WINNER) == COUCH) {
        tell("You'll have to get out of the couch first.\n");
        return true;
      } else if (!(hasFlag(g.PRSO, OPENBIT))) {
        return (await ALREADY("closed"));
      } else {
        return await DOOR_CLOSES();
      }
    } else if (isVerb(V.OPEN)) {
      if (hasFlag(g.PRSO, OPENBIT)) {
        return (await ALREADY("open"));
      } else if (hasFlag(AIRLOCK_INNER, OPENBIT)) {
        tell("A safety interlock prevents you from opening both doors of the airlock simultaneously.\n");
        return true;
      } else {
        setFlag(g.PRSO, OPENBIT);
        await VACUUM_HERE();
        if (!g.DOCKED$) {
          tell(" Outside the airlock is deep space. Beside the airlock is a safety hook to prevent you from drifting away into space.");
        }
        crlf();
        if (!g.SUIT_ON$) {
          await JIGS_UP(g.ACADEMY_DEATH);
        }
        return true;
      }
    } else if (!(hasFlag(g.PRSO, OPENBIT))) {
      return (await ALREADY("closed"));
    } else {
      clearFlag(g.PRSO, OPENBIT);
      return await AIR_HERE();
    }
  } else if (isVerb(V.LOOK_INSIDE)) {
    if (!(hasFlag(g.PRSO, OPENBIT))) {
      tell("The ", D(g.PRSO), " is closed and there is no viewport.\n");
      return true;
    } else if (g.PRSO == AIRLOCK_INNER) {
      tell("You see the bridge.\n");
      return true;
    } else if (g.DOCKED$) {
      tell("You see the red docking area of the artifact, including a dome with an airlock.\n");
      return true;
    } else {
      return await DESCRIBE_SPACE();
    }
  } else {
    return false;
  }
}

