async function DEEP_SPACE_FCN(rarg = false) {
  if (rarg == M_LOOK) {
    tell("You are floating outside the Starcross. The airlock door is ", S((hasFlag(AIRLOCK_OUTER, OPENBIT) ? "open" : "closed")));
    if (g.THAT_END) {
      tell(". One end of your safety line is attached to a hook next to the airlock.");
    } else {
      tell(". There is a hook next to the airlock.");
    }
    tell(" This is deep space, outside the plane of the ecliptic and far beyond the orbit of Earth. The sun seems small but still intolerably bright to look at directly.\n");
    return await DESCRIBE_SPACE();
  } else if (rarg == M_END) {
    if (!g.THIS_END || !g.THAT_END) {
      tell("You have left the Starcross in deep space without a safety line, a good way to drift into space and eventually run out of air.\n");
      if (40 > random(100)) {
        tell("So far you've been lucky and not drifted very far.\n");
      } else {
        (await JIGS_UP("In fact, this is exactly what has happened to you."));
      }
      return true;
    } else {
      return false;
    }
  } else if (rarg == M_BEG) {
    if (isVerb(V.THROW)) {
      return await THROW_AWAY();
    } else if (isVerb(V.REACH_FOR) && (g.PRSO == AIRLOCK_OUTER)) {
      if (hasFlag(AIRLOCK_OUTER, OPENBIT)) {
        tell("Just in time you pull yourself back into the airlock.\n\n");
        return await GOTO(SPACESHIP_AIRLOCK);
      } else {
        tell("You grab for the hatch, but can't find a handhold!\n");
        return true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

