async function DESCRIBE_SPACE() {
  if (g.DOCKED$) {
    tell(S(g.COLOR_CODED), "Your ship is tethered securely next to a large dome with an airlock. The surface looks metallic.\n");
    return true;
  } else if (g.VIEW_COUNT > 0) {
    tell(S(get(g.VIEW_TABLE, mod(g.VIEW_COUNT + 2, 4))), "\n");
    return true;
  } else if (g.TRIP_COUNT > 0) {
    if (g.LOST || !(g.DESTINATION == g.MASS)) {
      tell("There is nothing interesting visible.\n");
      return true;
    } else {
      tell(S(get(g.TRIP_DESCS, g.TRIP_COUNT)), "\n");
      return true;
    }
  } else {
    tell("You see the emptiness of space.\n");
    return true;
  }
}

