async function SPACESUIT_FCN() {
  if (isVerb(V.ZAP) && (loc(SPACESUIT) == CHIEF)) {
    await PERFORM(V.ZAP, ZAP_GUN, CHIEF);
    return true;
  } else if (isVerb(V.WEAR, V.BOARD)) {
    if (g.SUIT_ON$) {
      tell("You are already wearing it.\n");
      return true;
    } else if (!(await TRYTAKE())) {
      return true;
    } else {
      g.SUIT_ON$ = true;
      setFlag(SPACESUIT, WEARBIT);
      move(SPACESUIT, g.WINNER);
      tell("You are now wearing the space suit, breathing internal oxygen.\n");
      return true;
    }
  } else if (isVerb(V.TAKE_OFF, V.DISEMBARK)) {
    if (g.SUIT_ON$) {
      g.SUIT_ON$ = false;
      g.THIS_END = false;
      clearFlag(SPACESUIT, WEARBIT);
      if (hasFlag(g.HERE, SPACEBIT)) {
        return (await JIGS_UP("That was a silly thing to do, as there is no air here. You die of all sorts of asphyxiation."));
      } else if (g.POISON_COUNT == 4) {
        return (await JIGS_UP("The air is foul and unbreathable, and you pass out almost instantly after removing the space suit."));
      } else {
        tell("You have removed the space suit.");
        if (await ON_ARTIFACT$()) {
          return (await DESCRIBE_AIR(" The air here is "));
        } else {
          return crlf();
        }
      }
    } else {
      tell("You aren't wearing it.\n");
      return true;
    }
  } else if (isVerb(V.DROP, V.GIVE, V.THROW, V.PUT)) {
    if (g.SUIT_ON$) {
      tell("You'll have to take it off first!\n");
      return true;
    } else {
      g.THIS_END = false;
      return false;
    }
  } else if ((loc(SPACESUIT) == CHIEF) && isVerb(V.TAKE, V.POINT)) {
    tell("The chief jumps back, annoyed. He assumes you are trying to go back on your word.\n");
    return true;
  } else {
    return false;
  }
}

