async function SAFETY_LINE_FCN(rarg = false) {
  if (rarg == M_OBJDESC) {
    tell("A safety line");
    if (g.THIS_END && !(loc(SPACESUIT) == g.WINNER)) {
      g.THIS_END = false;
    }
    if (!(hasFlag(SAFETY_LINE, TOUCHBIT))) {
      tell(" hangs on the wall.\n");
      return true;
    } else if (g.THIS_END) {
      tell(" (attached to your space suit");
      if (g.THAT_END) {
        tell(" and a hook");
      }
      tell(")");
    } else if (g.THAT_END) {
      tell(" (attached to a hook)");
    }
    tell(" is here.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    if (g.THIS_END) {
      tell("One end of the line is attached to your space suit");
      if (g.THAT_END) {
        tell(", and one end to a hook");
      }
      tell(".\n");
      return true;
    } else if (g.THAT_END) {
      tell("One end of the line is attached to a hook.\n");
      return true;
    } else {
      tell("The line is not attached to anything.\n");
      return true;
    }
  } else if (isVerb(V.TIE, V.UNTIE)) {
    if (!(loc(SAFETY_LINE) == g.WINNER)) {
      await DONT_HAVE(SAFETY_LINE);
    } else if (isVerb(V.TIE)) {
      if (g.PRSI == SPACESUIT) {
        if (!(await HELD$(SPACESUIT))) {
          await DONT_HAVE(SPACESUIT);
          return true;
        } else if (g.THIS_END) {
          (await ALREADY("tied", SPACESUIT));
          return true;
        } else {
          g.THIS_END = SPACESUIT;
        }
      } else if (g.PRSI == SAFETY_HOOK) {
        if (g.THAT_END) {
          (await ALREADY("tied", SAFETY_HOOK));
          return true;
        } else {
          g.THAT_END = SAFETY_HOOK;
        }
      } else if (g.PRSI) {
        tell("You can't attach the safety line to that.\n");
        return true;
      } else {
        tell("You must tell what to attach it to.\n");
        return true;
      }
      tell("Attached to the ", D(g.PRSI), ".\n");
    } else if (isVerb(V.UNTIE)) {
      if (g.PRSI) {
        if (g.PRSI == g.THAT_END) {
          g.THAT_END = false;
        } else if (g.PRSI == g.THIS_END) {
          g.THIS_END = false;
        } else {
          tell("It's not attached to the ", D(g.PRSI), ".\n");
          return true;
        }
        tell("Detached from the ", D(g.PRSI), ".\n");
      } else if (g.THAT_END) {
        tell("Detached from the ", D(g.THAT_END), ".\n");
        g.THAT_END = false;
      } else if (g.THIS_END) {
        tell("Detached from the ", D(g.THIS_END), ".\n");
        g.THIS_END = false;
      } else {
        tell("It's not attached to anything.\n");
      }
    }
    return true;
  } else if (isVerb(V.PUT, V.DROP, V.THROW, V.GIVE, V.PUT_ON, V.TAKE)) {
    if (g.THIS_END || g.THAT_END) {
      tell("You should detach it first.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

