async function NEST_FCN() {
  let tool = false;
  if (isVerb(V.EXAMINE)) {
    tell("The nest is a jerry-built construction of odds and ends precariously stuck together. Rat-ants swarm all over it.\n");
    return true;
  } else if (isVerb(V.KICK)) {
    tell("Rat-ants nip at your toes and prevent it.\n");
    return true;
  } else if ((isVerb(V.MUNG) && (g.PRSO == NEST) && g.PRSI) || (isVerb(V.THROW) && (g.PRSI == NEST) && g.PRSO)) {
    if (isVerb(V.MUNG)) {
      tool = g.PRSI;
    } else {
      tool = g.PRSO;
    }
    if (tool == HANDS) {
      tell("Rat-ants snap at you with their nasty sharp mandibles.\n");
      return true;
    } else if (!(loc(tool) == g.WINNER)) {
      await DONT_HAVE(tool);
      return true;
    } else if (getProp(tool, P.SIZE) > 5) {
      setFlag(tool, NDESCBIT);
      move(tool, SMASHED_NEST);
      if (loc(RED_KEY) == NEST) {
        setFlag(RED_KEY, TOUCHBIT);
        setFlag(RED_KEY, NDESCBIT);
        move(RED_KEY, SMASHED_NEST);
      }
      move(SMASHED_NEST, NEST_CAGE);
      await ROB(NEST, SMASHED_NEST, true);
      remove(NEST);
      enable(await QUEUE(I_NEST.id, 15));
      tell("The nest smashes into fragments and the rat-ants stop dead in their tracks! They frantically evacuate the nest and immediately begin constructing a new nest at the opposite end of the cage. Rat-ant babies are being carried across the cage, and warriors watch you suspiciously.\n");
      return true;
    } else {
      setFlag(tool, NDESCBIT);
      move(tool, NEST);
      tell("The ", D(tool), " doesn't damage the nest very much, and in fact a rat-ant quickly incorporates it into the nest.\n");
      return true;
    }
  } else if (isVerb(V.ZAP)) {
    remove(NEST);
    disable(await INT(I_NEST.id));
    tell("The nest and all it contains is destroyed.\n");
    return true;
  } else {
    return false;
  }
}

