async function ZAP_GUN_FCN() {
  let i = 0;
  i = first(ZAP_GUN);
  if (isVerb(V.EXAMINE)) {
    tell("It looks like the heavy duty model. It's got quite a bit of heft to it, and you really need two hands to aim it properly. The barrel is long and festooned with strange knobs and antennae. There is a charge indicator which is unfortunately unreadable.\n");
    return true;
  } else if (isVerb(V.OPEN)) {
    tell("You can't open that.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE)) {
    if (i) {
      setFlag(ZAP_GUN, OPENBIT);
      tell("In the barrel is a ", D(i), "!\n");
      await SCORE_OBJ(i);
      return true;
    } else {
      tell("There is nothing inside the barrel.\n");
      return true;
    }
  } else if (isVerb(V.SHAKE) && i) {
    tell("It rattles loudly.\n");
    return true;
  } else if (isVerb(V.PUT) && (ZAP_GUN == g.PRSI)) {
    if (i) {
      tell("There is already something inside it.\n");
      return true;
    } else if (!(hasFlag(g.PRSO, KEYBIT))) {
      return await WONT_FIT();
    } else {
      return false;
    }
  } else if (isVerb(V.POINT)) {
    tell("Why don't you just fire it instead?\n");
    return true;
  } else if (isVerb(V.MUNG, V.ATTACK)) {
    tell("Firing the ray gun is more efficient than smashing things with it.\n");
    return true;
  } else if (isVerb(V.ZAP)) {
    if (!(loc(ZAP_GUN) == g.WINNER)) {
      tell("You are firing it by mental force, I assume?\n");
      return true;
    } else if (g.ZAP_CNT == 0) {
      tell("\"Click.\"\n");
      return true;
    }
    g.ZAP_CNT = g.ZAP_CNT - 1;
    if (i) {
      remove(i);
      setFlag(ZAP_GUN, OPENBIT);
      if (!(g.ZAP_CNT == 0)) {
        g.ZAP_CNT = g.ZAP_CNT - 1;
      }
      tell("A giant blast");
      if (i == SILVER_KEY) {
        tell(" of silvery rays");
      }
      tell(" issues from the barrel, but it doesn't go very far. In fact, there is a secondary explosion about a foot from the barrel, scattering dust motes in the air. There is almost no recoil: instead the gun vibrated almost painfully. This felt like a misfire.\n");
      return true;
    } else if (hasFlag(g.HERE, RAIRBIT)) {
      return await JATO();
    } else if (!g.PRSI) {
      tell("A giant blast of searing orange rays issues from the barrel, and the recoil knocks you flat on your back. Fortunately no one was standing in front of you or it would have been curtains.\n");
      return true;
    } else if (g.PRSI == ME || g.PRSI == HANDS) {
      await ROB(g.WINNER);
      return (await JIGS_UP("If you say so... The blast destroys you and your possessions so quickly there is no point in even describing the carnage."));
    } else if (g.PRSI == ZAP_GUN) {
      tell("That would involve a higher technology than even the builders of the ray gun possessed.\n");
      return true;
    } else if (hasFlag(g.PRSI, VILLAIN)) {
      remove(g.PRSI);
      tell("A mighty wash of orange rays and smoke covers the ", D(g.PRSI), ". The powerful blast knocks you down as the poor ", D(g.PRSI), " is utterly disintegrated.\n");
      return true;
    } else if (loc(g.PRSI) == g.WINNER) {
      await ROB(g.WINNER);
      tell("A huge explosion of orange rays destroys the ", D(g.PRSI), " utterly.\n");
      return (await JIGS_UP("Unfortunately, that requires firing so close that the blast destroys you and your possessions as well."));
    } else if (hasFlag(g.PRSI, TAKEBIT) || hasFlag(g.PRSI, VICBIT)) {
      remove(g.PRSI);
      tell("There is a horrendous explosion from the ray gun, and a huge gout of orange rays envelops the ", D(g.PRSI), ". You are knocked spinning by the recoil, and when you recover, you see no sign of the ", D(g.PRSI), " but a tiny drift of dust.\n");
      return true;
    } else {
      tell("An explosion of orange rays sweeps over the ", D(g.PRSI), ", but when the smoke clears, it is still there (though perhaps a bit singed).\n");
      return true;
    }
  } else if (isVerb(V.KILL, V.MUNG, V.ATTACK) && (ZAP_GUN == g.PRSI)) {
    await PERFORM(V.ZAP, g.PRSI, g.PRSO);
    return true;
  } else {
    return false;
  }
}

