async function DRIVE_BUBBLE_ROOM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("The drive bubble is on the axis of rotation at the aft end of the artifact, so there is no \"gravity\" here. It is transparent and you can see the tips of the tallest trees of the forest beyond. Far off, at the opposite end of the axis, is another bubble much like this one. ");
    if (loc(WHITE_KEY) == WHITE_SLOT) {
      tell("The room's gray walls are covered with traceries of white outlining controls, buttons, dials, and indicators. In addition, a black slot surrounded by an ominous dead-black circle is next to a white slot containing a white rod.");
    } else {
      tell("The room is a featureless gray except for one small white slot.");
    }
    tell(" One way out is the hatch, which is ");
    if (hasFlag(DRIVE_BUBBLE_HATCH, OPENBIT)) {
      tell("open.");
    } else {
      tell("closed.");
    }
    return crlf();
  } else if (rarg == M_BEG) {
    return await BUBBLE_BOUNCE();
  } else {
    return false;
  }
}

async function BUBBLE_BOUNCE() {
  if (isVerb(V.WALK) && (g.PRSO == P.UP || g.PRSO == P.NORTH)) {
    tell("You can't walk in that direction, as there is no gravity here. You could jump, perhaps...\n");
    return true;
  } else if (isVerb(V.LEAP)) {
    tell("You push off the floor, and because there is no weight you zoom into the air and rebound against the transparent surface of the bubble!\n");
    return true;
  } else {
    return false;
  }
}

async function WHITE_KEY_FCN() {
  if (isVerb(V.TAKE) && (loc(WHITE_KEY) == WHITE_SLOT)) {
    remove(BLACK_SLOT);
    clearFlag(WHITE_KEY, NDESCBIT);
    move(WHITE_KEY, g.WINNER);
    tell("When you remove the rod, the displays fade and the wall becomes featureless gray, except for the white slot.\n");
    return true;
  } else if (isVerb(V.PUT) && (await TRYTAKE()) && (g.PRSO == WHITE_KEY) && (g.PRSI == WHITE_SLOT)) {
    setFlag(WHITE_KEY, TOUCHBIT);
    setFlag(WHITE_KEY, NDESCBIT);
    move(BLACK_SLOT, DRIVE_BUBBLE_ROOM);
    move(WHITE_KEY, WHITE_SLOT);
    tell("As you insert the rod, the walls come alive with a white tracery of controls, dials, and gauges. In addition, a black slot surrounded by an ominous dead-black circle appears.\n");
    return true;
  } else {
    return false;
  }
}

async function ON_DRIVE_BUBBLE_FCN(rarg) {
  if (rarg == M_BEG) {
    return await ON_BUBBLE_FCN(DRIVE_BUBBLE, AXIS_1);
  } else {
    return false;
  }
}

async function SILVER_SLOT_CONT() {
  return await HATCH_CLOSE(DRIVE_BUBBLE_HATCH);
}

async function GOLD_SLOT_CONT() {
  return await HATCH_CLOSE(CONTROL_BUBBLE_HATCH);
}

async function HATCH_CLOSE(hatch) {
  let cont = 0;
  if (isVerb(V.TAKE)) {
    cont = first(hatch);
    if (await TRYTAKE()) {
      tell("The ", D(hatch), " closes silently.\n");
      clearFlag(cont, NDESCBIT);
      return clearFlag(hatch, OPENBIT);
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function SILVER_SLOT_FCN() {
  return await SLOT_DOOR(SILVER_SLOT, SILVER_KEY, DRIVE_BUBBLE_HATCH);
}

async function GOLD_SLOT_FCN() {
  return await SLOT_DOOR(GOLD_SLOT, GOLD_KEY, CONTROL_BUBBLE_HATCH);
}

async function SLOT_DOOR(slot, key, door) {
  if (isVerb(V.PUT)) {
    if (g.PRSO == key) {
      if (!(hasFlag(door, OPENBIT))) {
        setFlag(door, OPENBIT);
        setFlag(key, NDESCBIT);
        move(key, slot);
        tell("The ", D(g.PRSO), " slides into the slot and the ", D(door), " opens.\n");
        return true;
      } else {
        return (await ALREADY("open"));
      }
    } else if (hasFlag(g.PRSO, KEYBIT)) {
      return await WRONG_KEY();
    } else {
      return await WONT_FIT();
    }
  } else {
    return false;
  }
}

async function WHITE_SLOT_FCN() {
  if (isVerb(V.PUT)) {
    if (!(await TRYTAKE())) {
      return true;
    } else if (!(hasFlag(g.PRSO, KEYBIT))) {
      tell("You can't do that.\n");
      return true;
    } else if (g.PRSO == WHITE_KEY) {
      return false;
    } else if (loc(WHITE_KEY) == WHITE_SLOT) {
      tell("The white crystal rod is already in the slot.\n");
      return true;
    } else if (hasFlag(g.PRSO, KEYBIT)) {
      return await WRONG_KEY();
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function BLACK_SLOT_FCN() {
  if (isVerb(V.PUT)) {
    if (!(await TRYTAKE())) {
      return true;
    } else if (!(hasFlag(g.PRSO, KEYBIT))) {
      tell("You can't do that.\n");
      return true;
    } else if (g.PRSO == BLACK_KEY) {
      tell("As the rod slides easily into the slot, the lights go out in the bubble. Outside, you can see dead black night settling over everything. An expressionless voice speaks inside your head: \"Emergency shutoff mechanism activated...\" The voice gets quieter and quieter, and finally silence rules over all.\n");
      return await FINISH();
    } else if (hasFlag(g.PRSO, KEYBIT)) {
      return await WRONG_KEY();
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function CONTROL_BUBBLE_ENTRANCE_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("You are floating outside a 100 meter crystal dome which protrudes from the fore end of the cylinder. Inside, you can discern shadowy mechanisms and odd constructions. Near you is an entrance which is ");
    if (hasFlag(CONTROL_BUBBLE_HATCH, OPENBIT)) {
      tell("open.");
    } else {
      tell("closed.");
    }
    tell(" A small slot surrounded by gold crystal is next to the hatch.");
    if (loc(GOLD_KEY) == GOLD_SLOT) {
      tell(" The slot contains a gold rod.");
    }
    tell(" Small knobs which might make good handholds dot the surface of the bubble from the axis to the hatch.\n");
    return true;
  } else if (rarg == M_BEG) {
    if (isVerb(V.DROP, V.THROW)) {
      return await BOMBS_AWAY();
    } else {
      return await SWAN_DIVE(CONTROL_BUBBLE);
    }
  } else {
    return false;
  }
}

async function CONTROL_BUBBLE_ROOM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("This room must be the main control room of the artifact. The control bubble itself is transparent and you can look out upon the interior of the artifact. Far off, hidden among the tallest trees of the forest, is the matching drive bubble. One way out is the hatch, which is ");
    if (hasFlag(CONTROL_BUBBLE_HATCH, OPENBIT)) {
      tell("open.");
    } else {
      tell("closed.");
    }
    crlf();
    tell("The walls are gray ");
    if (loc(CLEAR_KEY) == CLEAR_SLOT) {
      tell("except for five small color-coded slots (pink, brown, violet, green, and blue) ");
      if (loc(CLEAR_SLOT) == g.HERE) {
        tell("surrounding a small clear one.");
      } else {
        tell("arranged in a pentagon.");
      }
    } else {
      tell("except for a single small slot surrounded by clear crystal.");
    }
    crlf();
    await SLOTS_AND_SPOTS();
    if (loc(VIEW_SELECT) == g.HERE) {
      await apply(getProp(VIEW_SELECT, P.ACTION), M_OBJDESC);
    }
    return true;
  } else if (rarg == M_BEG) {
    return await BUBBLE_BOUNCE();
  } else {
    return false;
  }
}

async function PLANTER_FCN() {
  if (isVerb(V.EXAMINE)) {
    return await AS_ADVERTISED();
  } else if (isVerb(V.DIG)) {
    tell("You find nothing of interest.\n");
    return true;
  } else {
    return false;
  }
}

async function METAL_BAND_EXIT() {
  if (!(hasFlag(GRASSLAND, TOUCHBIT))) {
    enable(await QUEUE(I_HUNTERS.id, 2));
  }
  tell("You climb a vertical shaft for a considerable distance. The shaft opens into a gigantic space which obviously occupies most of the interior of the artifact. The area is ", S((g.NIGHT$ ? "dimly" : "brightly")), " lit and has an interesting geography...\n\n");
  return GRASSLAND;
}

async function SEES_HUNTERS$() {
  return (g.HERE == GRASSLAND || g.HERE == GRASSLAND_2 || g.HERE == FORE_END) || (g.HERE == METAL_BAND || g.HERE == METAL_BAND_2 || g.HERE == FORE_END_2) || (g.HERE == SCRUB || g.HERE == SCRUB_2);
}

async function I_HUNTERS() {
  if (g.HUNTER_COUNT == 0) {
    if ((40 > random(100)) && (await SEES_HUNTERS$())) {
      g.HUNTER_COUNT = 1;
    } else {
      enable(await QUEUE(I_HUNTERS.id, 2));
    }
  }
  if (!(g.HUNTER_COUNT == 0)) {
    if (await SEES_HUNTERS$()) {
      tell("There is activity ");
      if (g.HERE == GRASSLAND) {
        tell("above, across the cylinder: ");
      } else if (g.HERE == GRASSLAND_2) {
        tell("nearby: ");
      } else {
        tell("on the grassy plain: ");
      }
      tell(S(get(g.HUNTER_TABLE, g.HUNTER_COUNT)), "\n");
    }
    if (g.HUNTER_COUNT < get(g.HUNTER_TABLE, 0)) {
      g.HUNTER_COUNT = g.HUNTER_COUNT + 1;
      return enable(await QUEUE(I_HUNTERS.id, 2));
    } else {
      g.HUNTER_COUNT = 0;
      return enable(await QUEUE(I_HUNTERS.id, 200));
    }
  } else {
    return false;
  }
}

async function UNICORNS_FCN() {
  if (isVerb(V.EXAMINE)) {
    if (g.HERE == GRASSLAND) {
      tell("They are over on the other side of the cylinder.\n");
      return true;
    } else {
      tell("They are nearby, cropping grass.\n");
      return true;
    }
  } else if (isVerb(V.FOLLOW)) {
    tell("They aren't going anywhere.\n");
    return true;
  } else if (isVerb(V.ZAP)) {
    if (await CAN_ZAP$()) {
      tell("Many unicorns are incinerated; the rest scatter in terror, then slowly form back into a herd some distance away.\n");
      return await SPOILED_HUNT();
    } else {
      return false;
    }
  } else {
    tell("The creatures move off as you approach, so you can't get very close to them.\n");
    await SPOILED_HUNT();
    return false;
  }
}

async function SPOILED_HUNT() {
  if ((g.HUNTER_COUNT > 0) && (g.HUNTER_COUNT < 4)) {
    g.HUNTER_COUNT = 0;
    enable(await QUEUE(I_HUNTERS.id, 200));
    tell("You have disturbed the hunters, who are annoyed, and the unicorns, who are now more wary. The hunt is spoiled.\n");
  }
  return true;
}

async function I_NIGHT() {
  enable(await QUEUE(I_NIGHT.id, 128));
  if ((await SEES_HUNTERS$()) || (g.HERE == FOREST || g.HERE == BASE_OF_TREE || g.HERE == UP_A_TREE) || (g.HERE == TREETOP_ROOM || g.HERE == DRIVE_BUBBLE_ENTRANCE || g.HERE == CONTROL_BUBBLE_ENTRANCE) || (g.HERE == AXIS_1 || g.HERE == AXIS_2 || g.HERE == AXIS_3) || (g.HERE == ON_DRIVE_BUBBLE || g.HERE == ON_CONTROL_BUBBLE)) {
    if (g.NIGHT$) {
      tell("The lights come on: it is now full daylight.\n");
    } else {
      tell("The lights dim: it is now nighttime. There is still enough light to see by; it's like a clear, moonlit night back on earth.\n");
    }
  }
  return g.NIGHT$ = !g.NIGHT$;
}

async function BOMBS_AWAY() {
  let a_ = 0, b = 0;
  if (g.PRSO == RED_DISK || g.PRSO == BLUE_DISK) {
    await DISK_SWITCH(g.PRSO, true);
  }
  if (!(await IDROP())) {
    return true;
  } else if ((g.PRSO == SPACESUIT || g.PRSO == SAFETY_LINE) && (await apply(getProp(g.PRSO, P.ACTION)))) {
    return true;
  } else if (g.PRSI == DRIVE_BUBBLE || g.PRSI == CONTROL_BUBBLE) {
    move(g.PRSO, g.PRSI == DRIVE_BUBBLE ? FOREST : FORE_END);
    tell("Throwing the ", D(g.PRSO), " provides some impulse away from the ", D(g.PRSI), ", but air resistance slows you quickly.\n");
    return true;
  } else {
    if (g.HERE == ON_DRIVE_BUBBLE || g.HERE == DRIVE_BUBBLE_ENTRANCE) {
      a_ = FOREST;
      b = BASE_OF_TREE;
    } else if (g.HERE == AXIS_1) {
      a_ = SCRUB;
      b = SCRUB_2;
    } else if (g.HERE == AXIS_2) {
      a_ = GRASSLAND;
      b = GRASSLAND_2;
    } else if (g.HERE == AXIS_3) {
      a_ = METAL_BAND;
      b = METAL_BAND_2;
    } else if (g.HERE == ON_CONTROL_BUBBLE || g.HERE == CONTROL_BUBBLE_ENTRANCE) {
      a_ = FORE_END;
      b = FORE_END_2;
    }
    move(g.PRSO, 50 > random(100) ? a_ : b);
    tell("The ", D(g.PRSO), " sails away, drifting in a long arc towards the ground.\n");
    return true;
  }
}

async function ON_BUBBLE_FCN(bub, dest) {
  if (isVerb(V.DROP, V.THROW)) {
    return await BOMBS_AWAY();
  } else if (isVerb(V.LEAP) || (isVerb(V.PUSH) && (g.PRSO == bub))) {
    tell("You push against the surface of the bubble, and because there is no weight here, you shoot into the air and away along the axis!\n");
    crlf();
    await GOTO(dest);
    return true;
  } else {
    return false;
  }
}

async function ON_CONTROL_BUBBLE_FCN(rarg) {
  if (rarg == M_BEG) {
    return await ON_BUBBLE_FCN(CONTROL_BUBBLE, AXIS_3);
  } else {
    return false;
  }
}

async function AXIS_FCN(rarg = false) {
  if (rarg == M_BEG) {
    if (isVerb(V.WALK)) {
      tell("You are floating in midair near the axis of rotation. Given this fact, it's hard to see how you are going to walk anywhere.\n");
      return true;
    } else if (isVerb(V.DROP, V.THROW)) {
      return await BOMBS_AWAY();
    } else if (isVerb(V.LEAP)) {
      tell("That was a good idea when you had something to push against. Here it has no effect.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function JATO() {
  let target = 0;
  target = g.PRSI;
  if (!(target == DRIVE_BUBBLE || target == CONTROL_BUBBLE || target == GROUND)) {
    target = 40 > random(100) ? DRIVE_BUBBLE : (40 > random(100) ? CONTROL_BUBBLE : GROUND);
  }
  tell("A blast of orange flame issues from the gun, and the recoil propels you at an impressive speed through the air.");
  if (g.HERE == DRIVE_BUBBLE_ROOM || g.HERE == CONTROL_BUBBLE_ROOM) {
    tell(" You hit the bulkhead rather hard. Ouch!\n");
    return true;
  } else if (target == DRIVE_BUBBLE || target == CONTROL_BUBBLE) {
    tell(" Eventually, air resistance slows you down, but you are still in the weightless area near the center of the cylinder.\n");
    if (target == DRIVE_BUBBLE) {
      crlf();
      if (g.HERE == ON_DRIVE_BUBBLE) {
        await GOTO(AXIS_1);
      } else if (g.HERE == AXIS_1) {
        await GOTO(AXIS_2);
      } else if (g.HERE == AXIS_2) {
        await GOTO(AXIS_3);
      } else if (g.HERE == AXIS_3) {
        await GOTO(ON_CONTROL_BUBBLE);
      } else if (g.HERE == ON_CONTROL_BUBBLE) {
        tell("You are still outside the control bubble.\n");
      }
    } else {
      crlf();
      if (g.HERE == ON_DRIVE_BUBBLE) {
        tell("You are still outside the drive bubble.\n");
      } else if (g.HERE == AXIS_1) {
        await GOTO(ON_DRIVE_BUBBLE);
      } else if (g.HERE == AXIS_2) {
        await GOTO(AXIS_1);
      } else if (g.HERE == AXIS_3) {
        await GOTO(AXIS_2);
      } else if (g.HERE == ON_CONTROL_BUBBLE) {
        await GOTO(AXIS_3);
      }
    }
    return true;
  } else if (target == GROUND) {
    return (await JIGS_UP(" You are now some distance from the axis of the cylinder. Air resistance and centripetal force take hold and you start to fall in a lovely arc that ends as you splatter against the ground."));
  } else {
    return false;
  }
}

async function OBSERVATORY_FCN(rarg) {
  let x = 0;
  if (rarg == M_LOOK) {
    x = first(SLIDE_PROJECTOR);
    tell("This is the interior part of the artifact's observatory, with an exit to starboard. There are no telescopes or other instruments visible");
    if (!x || hasFlag(x, KEYBIT)) {
      tell(", but in the center of the room is an image of space in the vicinity. Examining the image, you see a tiny model of the solar system. The sun is a bright dot in the center; Jupiter and Saturn are easily discovered.");
      if (x) {
        tell(" The colors of the dots are not what you would expect, though,");
        if (loc(CLEAR_KEY) == SLIDE_PROJECTOR) {
          tell(" and range throughout the spectrum.");
        } else if (hasFlag(x, KEYBIT)) {
          tell(" as they are filtered through a ", D(x), ".");
        }
      }
    } else {
      tell(", only a holographic projector.");
    }
    return crlf();
  } else {
    return false;
  }
}

async function SLIDE_PROJECTOR_FCN() {
  let x = 0;
  if (isVerb(V.EXAMINE)) {
    x = first(SLIDE_PROJECTOR);
    if (x && !(hasFlag(x, KEYBIT))) {
      tell("The projector is a type of laser, currently blocked by a ", D(x), " from projecting any light.\n");
      return true;
    } else {
      tell("The projector is a type of laser, producing a continuous holographic view of space outside the artifact. The light issues from the front of the projector, and is blindingly bright.\n");
      return true;
    }
  } else if (isVerb(V.LOOK_SAFELY)) {
    if (g.PRSI == SMOKED_GLASS || g.PRSI == BLACK_KEY) {
      tell("The light is very bright, but the ", D(g.PRSI), " filters it enough so that you are not blinded.\n");
      if (loc(CLEAR_KEY) == SLIDE_PROJECTOR) {
        clearFlag(CLEAR_KEY, INVISIBLE);
        tell("Inside the projector is a clear crystal rod, which has a prismatic effect on the light being emitted.\n");
        return true;
      } else {
        return false;
      }
    } else {
      return (await JIGS_UP("The light is filtered somewhat by the rod, but not enough, and you are blinded. You blunder about for a while, end up in a dark place, and are set upon by grues."));
    }
  } else if (isVerb(V.LOOK_INSIDE)) {
    return (await JIGS_UP("The light being emitted is so bright that your retina is scorched and you are blinded. You blunder about for a while, end up in a dark place, and are set upon by grues."));
  } else if (isVerb(V.TAKE) && (loc(g.PRSO) == SLIDE_PROJECTOR)) {
    move(g.PRSO, g.WINNER);
    tell("Taken. ");
    if (hasFlag(g.PRSO, KEYBIT)) {
      await SCORE_OBJ(g.PRSO);
      tell("The image displayed is now clear and correctly colored.\n");
      return true;
    } else {
      tell("The displayed image becomes visible again.\n");
      return true;
    }
  } else if (isVerb(V.PUT) && (g.PRSI == SLIDE_PROJECTOR)) {
    if (first(g.PRSI)) {
      tell("There is already something there.\n");
      return true;
    } else if (g.PRSO == CLEAR_KEY) {
      move(g.PRSO, g.PRSI);
      tell("The displayed image is now prismatic and multi-colored.\n");
      return true;
    } else if (hasFlag(g.PRSO, KEYBIT)) {
      move(g.PRSO, g.PRSI);
      tell("The displayed image is now filtered through a ", D(g.PRSO), ", and becomes that color.\n");
      return true;
    } else {
      return await WONT_FIT();
    }
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    tell("You can't do that to the ", D(g.PRSO), ".\n");
    return true;
  } else {
    return false;
  }
}

async function LASER_BEAM_FCN() {
  if (isVerb(V.EXAMINE)) {
    tell("The beam projects a view of some outside location.\n");
    return true;
  } else if (isVerb(V.ZAP) && (await CAN_ZAP$())) {
    tell("Zapping a light beam is a waste of time.\n");
    return true;
  } else if (isVerb(V.MUNG)) {
    tell("The image vanishes while the beam is broken.\n");
    return true;
  } else {
    return false;
  }
}

async function CANT_DAMAGE() {
  tell("It's hard to see how you expect to damage a ", D(g.PRSO), ".\n");
  return true;
}

async function CONTROL_SLOT_FCN() {
  let f = 0;
  if (isVerb(V.PUT)) {
    if (!(hasFlag(g.PRSO, KEYBIT)) || first(g.PRSI)) {
      await WONT_FIT();
      return true;
    } else if (f = getProp(g.PRSI, P.KEY)) {
      if (!g.SWITCH_ON$ || !(loc(CARD) == SLOT)) {
        tell("The ", D(g.PRSI), " rejects the ", D(g.PRSO), ", and the slot flashes as if indicating a fault somewhere in the system.\n");
        return true;
      } else if (!(g.PRSO == f)) {
        await WRONG_KEY();
        return true;
      }
    }
    move(g.PRSO, g.PRSI);
    setFlag(g.PRSO, NDESCBIT);
    if ((g.PRSO == CLEAR_KEY) && (g.PRSI == CLEAR_SLOT)) {
      move(BROWN_SLOT, g.HERE);
      move(PINK_SLOT, g.HERE);
      move(GREEN_SLOT, g.HERE);
      move(BLUE_SLOT, g.HERE);
      move(VIOLET_SLOT, g.HERE);
      move(CLEAR_KEY, CLEAR_SLOT);
      tell("As you insert the clear rod, five other slots appear evenly ranged around the clear one. These are colored brown, green, blue, violet and pink respectively.\n");
      return true;
    } else if ((g.PRSO == BROWN_KEY) && (g.PRSI == BROWN_SLOT)) {
      f = TARGET_SELECT;
    } else if ((g.PRSO == PINK_KEY) && (g.PRSI == PINK_SLOT)) {
      f = VIEW_SELECT;
    } else if ((g.PRSO == GREEN_KEY) && (g.PRSI == GREEN_SLOT)) {
      f = SPEED_SELECT;
    } else if ((g.PRSO == BLUE_KEY) && (g.PRSI == BLUE_SLOT)) {
      f = EXECUTE_BUTTON;
    } else if ((g.PRSO == VIOLET_KEY) && (g.PRSI == VIOLET_SLOT)) {
      f = COURSE_SELECT;
    } else {
      return false;
    }
    move(f, g.HERE);
    tell("When the ", D(g.PRSO), " is inserted into the ", D(g.PRSI), ", a ghostly image appears on the wall alongside it");
    if (loc(CLEAR_SLOT) == CONTROL_BUBBLE_ROOM) {
      remove(CLEAR_SLOT);
      tell(", but the clear slot and its contents fade from view.\n");
    } else {
      tell(".\n");
    }
    if (f == VIEW_SELECT) {
      await PERFORM(V.EXAMINE, f);
    } else {
      tell("The image is a ", D(f), " which almost seems to project out of the wall.\n");
    }
    return true;
  } else if (isVerb(V.TAKE, V.TAKE_OFF)) {
    if ((g.PRSO == CLEAR_KEY) && (loc(g.PRSO) == CLEAR_SLOT)) {
      g.VIEW_STATUS = 0;
      g.TARGET = 0;
      g.COURSE_SHAPE = 0;
      g.SPEED_VALUE = 0;
      remove(VIEW_SELECT);
      remove(TARGET_SELECT);
      remove(SPEED_SELECT);
      remove(COURSE_SELECT);
      remove(EXECUTE_BUTTON);
      remove(BROWN_SLOT);
      remove(PINK_SLOT);
      remove(GREEN_SLOT);
      remove(BLUE_SLOT);
      remove(VIOLET_SLOT);
      move(CLEAR_KEY, g.WINNER);
      tell("When you remove the clear rod, the room returns to its original featureless state.\n");
      return true;
    } else if ((g.PRSO == BROWN_KEY) && (loc(g.PRSO) == BROWN_SLOT)) {
      g.TARGET = 0;
      f = TARGET_SELECT;
    } else if ((g.PRSO == PINK_KEY) && (loc(g.PRSO) == PINK_SLOT)) {
      g.VIEW_STATUS = 0;
      g.TARGET = 0;
      g.COURSE_SHAPE = 0;
      g.SPEED_VALUE = 0;
      f = VIEW_SELECT;
    } else if ((g.PRSO == GREEN_KEY) && (loc(g.PRSO) == GREEN_SLOT)) {
      g.SPEED_VALUE = 0;
      f = SPEED_SELECT;
    } else if ((g.PRSO == BLUE_KEY) && (loc(g.PRSO) == BLUE_SLOT)) {
      f = EXECUTE_BUTTON;
    } else if ((g.PRSO == VIOLET_KEY) && (loc(g.PRSO) == VIOLET_SLOT)) {
      g.COURSE_SHAPE = 0;
      f = COURSE_SELECT;
    } else {
      return false;
    }
    remove(f);
    move(g.PRSO, g.WINNER);
    clearFlag(g.PRSO, NDESCBIT);
    tell("The ", D(f), " fades from view as you take the ", D(g.PRSO));
    if ((loc(BROWN_KEY) == BROWN_SLOT) || (loc(BLUE_KEY) == BLUE_SLOT) || (loc(GREEN_KEY) == GREEN_SLOT) || (loc(PINK_KEY) == PINK_SLOT) || (loc(VIOLET_KEY) == VIOLET_SLOT)) {
      tell(".\n");
      return true;
    } else {
      move(CLEAR_SLOT, CONTROL_BUBBLE_ROOM);
      tell(", and a moment later the clear slot and its contents reappear.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function SLOTS_AND_SPOTS() {
  let cnt = 0, off = 0, scnt = 0, tbl = 0;
  if (!(loc(CLEAR_KEY) == CLEAR_SLOT)) {
    return true;
  } else {
    if (loc(CLEAR_SLOT) == g.HERE) {
      tell("A clear rod is in the clear slot. Of the surrounding slots, ");
    } else {
      tell("Of the colored slots, ");
    }
    if (loc(PINK_KEY) == PINK_SLOT) {
      tell("the pink one contains a pink rod and ");
    }
    if (loc(BROWN_KEY) == BROWN_SLOT) {
      cnt = cnt + 1;
    }
    if (loc(GREEN_KEY) == GREEN_SLOT) {
      cnt = cnt + 1;
    }
    if (loc(BLUE_KEY) == BLUE_SLOT) {
      cnt = cnt + 1;
    }
    if (loc(VIOLET_KEY) == VIOLET_SLOT) {
      cnt = cnt + 1;
    }
    if (cnt == 0) {
      if (loc(PINK_KEY) == PINK_SLOT) {
        tell("the others");
      } else {
        tell("all");
      }
      tell(" are empty.\n");
      return true;
    }
    tell("the ");
    tbl = g.SLOT_TABLE;
    scnt = cnt;
    loop1: for (;;) {
      if (get(tbl, off) == 0) {
        break loop1;
      } else if (loc(get(tbl, off)) == get(tbl, off + 1)) {
        tell(S(get(tbl, off + 2)));
        if (cnt > 2) {
          tell(", ");
        } else if (cnt == 2) {
          tell(" and ");
        }
        if ((cnt = cnt - 1) < 1) {
          break loop1;
        }
      }
      off = off + 3;
    }
    tell(" rod");
    if (scnt == 1) {
      tell(" is");
    } else {
      tell("s are");
    }
    tell(" in place in the like-colored slot");
    if (scnt == 1) {
      tell(". Alongside it is a spot");
    } else {
      tell("s. Alongside each of those are spots");
    }
    tell(" of the same color.\n");
    return true;
  }
}

async function VIEW_SELECT_FCN(rarg = false) {
  if ((rarg == M_OBJDESC) || isVerb(V.EXAMINE)) {
    tell("The pink screen includes a small square, a large square, and a display showing nearby space. This view shows ", S(get(g.VIEW_SCREEN_VIEWS, g.VIEW_STATUS)), ".");
    if ((g.VIEW_STATUS == 1) && !(g.TARGET == 0)) {
      tell(" The symbol representing ", S(get(g.TARGETS, g.TARGET)), " is lit.");
      if (!(g.COURSE_SHAPE == 0)) {
        tell(" A line on the display connects the position of the artifact with that of ", S(get(g.TARGETS, g.TARGET)), ", and terminating ", S(get(g.COURSES, g.COURSE_SHAPE)), S(get(g.TARGETS, g.TARGET)), ".");
        if (!(g.SPEED_VALUE == 0)) {
          tell(" The line is made of dots, blinking ", S(get(g.SPEEDS, g.SPEED_VALUE)), ", starting with the dot at the artifact and ending at the one next to ", S(get(g.TARGETS, g.TARGET)), ".");
        }
      }
    }
    return crlf();
  } else if (isVerb(V.RUB, V.PUSH)) {
    if (g.PRSO == ZOOM_IN) {
      if (g.VIEW_STATUS > 0) {
        g.VIEW_STATUS = g.VIEW_STATUS - 1;
        tell("The view screen now shows ", S(get(g.VIEW_SCREEN_VIEWS, g.VIEW_STATUS)), ".\n");
        return true;
      } else {
        tell("The view is unchanged.\n");
        return true;
      }
    } else if (g.PRSO == ZOOM_OUT) {
      if (g.VIEW_STATUS < 4) {
        g.VIEW_STATUS = g.VIEW_STATUS + 1;
        tell("The view screen now shows ", S(get(g.VIEW_SCREEN_VIEWS, g.VIEW_STATUS)), ".\n");
        return true;
      } else {
        tell("The view is unchanged.\n");
        return true;
      }
    } else {
      tell("The display flashes briefly.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function TARGET_SELECT_FCN() {
  if (isVerb(V.RUB, V.PUSH)) {
    if ((loc(VIEW_SELECT) == g.HERE) && (g.VIEW_STATUS == 1)) {
      g.TARGET = mod(g.TARGET + 1, 7);
      if (g.TARGET == 0) {
        tell("Now nothing is highlighted on the view screen.\n");
        return true;
      } else {
        tell("The view screen now shows ", S(get(g.TARGETS, g.TARGET)), " brightly highlighted.\n");
        return true;
      }
    } else {
      return await SPOT_FLASH();
    }
  } else {
    return false;
  }
}

async function SPEED_SELECT_FCN() {
  if (isVerb(V.RUB, V.PUSH)) {
    if (loc(VIEW_SELECT) == g.HERE) {
      if (!(g.COURSE_SHAPE == 0) && !(g.TARGET == 0)) {
        if (!(loc(WHITE_KEY) == WHITE_SLOT)) {
          tell("The line on the display flashes brightly, insistently, for about five seconds, and then returns to its former state.\n");
          return true;
        }
        g.SPEED_VALUE = mod(g.SPEED_VALUE + 1, 3);
        if (!(g.SPEED_VALUE == 0)) {
          tell("The line on the display now consists of dots which flash ", S(get(g.SPEEDS, g.SPEED_VALUE)), ", one at a time, starting with a dot at the artifact and concluding at ", S(get(g.TARGETS, g.TARGET)), ".\n");
          return true;
        } else {
          tell("The line on the display is now a solid line.\n");
          return true;
        }
      } else {
        return await SPOT_FLASH();
      }
    } else {
      return await SPOT_FLASH();
    }
  } else {
    return false;
  }
}

async function COURSE_SELECT_FCN() {
  if (isVerb(V.RUB, V.PUSH)) {
    if (loc(VIEW_SELECT) == g.HERE) {
      g.COURSE_SHAPE = mod(g.COURSE_SHAPE + 1, 5);
      if (!(g.TARGET == 0)) {
        if (!(g.COURSE_SHAPE == 0)) {
          tell("The highlighted image of ", S(get(g.TARGETS, g.TARGET)), " now is connected to that of the artifact. The line terminates ", S(get(g.COURSES, g.COURSE_SHAPE)), S(get(g.TARGETS, g.TARGET)), ".\n");
          return true;
        } else {
          tell("A line no longer connects the artifact and ", S(get(g.TARGETS, g.TARGET)), ".\n");
          return true;
        }
      } else {
        return await SPOT_FLASH();
      }
    } else {
      return await SPOT_FLASH();
    }
  } else {
    return false;
  }
}

async function EXECUTE_BUTTON_FCN(rarg = false) {
  if (isVerb(V.PUSH, V.RUB)) {
    if (loc(VIEW_SELECT) == g.HERE) {
      if (!(g.COURSE_SHAPE == 0) && !(g.TARGET == 0) && !(g.SPEED_VALUE == 0) && (g.VIEW_STATUS == 1)) {
        if (g.CONTROL_SCORE > 0) {
          await SCORE_UPD(g.CONTROL_SCORE);
          g.CONTROL_SCORE = 0;
          tell("All the displays flash once. There is a sensation of movement as the artifact positions itself to follow the course you have set.\n");
          return await WIN_GAME();
        } else {
          return await SPOT_FLASH();
        }
      } else {
        return await SPOT_FLASH();
      }
    } else {
      return await SPOT_FLASH();
    }
  } else {
    return false;
  }
}

async function SPOT_FLASH() {
  tell("The spot flashes briefly.\n");
  return true;
}

async function WIN_GAME() {
  crlf();
  if (g.TARGET == 4) {
    if (g.COURSE_SHAPE == 3 || g.COURSE_SHAPE == 4) {
      await SCORE_UPD(25);
      g.WON_FLAG = true;
      tell("The artifact, under your assured control, moves serenely toward Earth, where the knowledge it contains will immeasureably benefit mankind. Within a few years, there could be human ships flying out to the stars, and all because of your daring and cunning...\n\nA holographic projection of a humanoid figure appears before you. The being, tall and thin, swathed in shimmering robes, speaks in your own language. \"Congratulations, you who have passed our test. You have succeeded where others failed. Your race shall benefit thereby.\" He smiles. \"I expect to see you in person, someday.\" The projection fades.\n\n");
    } else {
      tell("The artifact approaches Earth, where the plaudits of humanity await you. Unfortunately, the course you have chosen ", S((g.COURSE_SHAPE == 1 ? "rams you into the planet and you earn the hatred of mankind, not its praises." : "loops you around the Earth and back into interstellar space, never to return.")));
      crlf();
    }
  } else {
    tell("The artifact moves confidently towards ", S(get(g.TARGETS, g.TARGET)), ", but its computer system is smart enough to know where you came from, so it realizes that you have made the wrong choice. All systems shut down, and silence settles over all.\n");
  }
  return await FINISH();
}

async function ON_ARTIFACT$() {
  if ((g.HERE == SPACESHIP_BRIDGE || g.HERE == SPACESHIP_STORES || g.HERE == SPACESHIP_QUARTERS) || (g.HERE == SPACESHIP_AIRLOCK || g.HERE == DEEP_SPACE || g.HERE == RED_DOCK) || (g.HERE == BLUE_DOCK || g.HERE == YELLOW_DOCK || g.HERE == GREEN_DOCK) || (g.HERE == OUTER_SPACE)) {
    return false;
  } else {
    return true;
  }
}

async function CARD_F() {
  if (loc(CARD) == SLOT) {
    if (isVerb(V.ZAP) && (await CAN_ZAP$())) {
      g.SWITCH_ON$ = false;
      g.MELTED$ = true;
      return false;
    } else if (isVerb(V.TAKE) && g.SWITCH_ON$) {
      tell("You get a giant shock as you try to take it.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function ROD_RACK_FCN() {
  if (isVerb(V.TAKE) && (loc(g.PRSO) == ROD_RACK)) {
    tell("When you take the ", D(g.PRSO), ", the hole it was in closes up as though it had never existed.\n");
    move(g.PRSO, g.WINNER);
    return true;
  } else if (isVerb(V.PUT) && (g.PRSI == ROD_RACK)) {
    if (loc(g.PRSO) == ROD_RACK) {
      tell("It's already there.\n");
      return true;
    } else if (!(await TRYTAKE())) {
      return true;
    } else if (hasFlag(g.PRSO, KEYBIT)) {
      move(g.PRSO, ROD_RACK);
      await SCORE_OBJ(g.PRSO);
      tell("The ", D(g.PRSO), " is inserted, and immediately another hole opens beside it.\n");
      return true;
    } else {
      return await WONT_FIT();
    }
  } else {
    return false;
  }
}

async function HATCH_DOOR_F() {
  if (isVerb(V.OPEN, V.CLOSE)) {
    tell("You can't manually open or close the hatch.\n");
    return true;
  } else {
    return false;
  }
}

async function SPEAR_F() {
  let obj = 0;
  if (g.HERE == NEST_CAGE) {
    obj = RAT_ANT;
  } else {
    obj = ALIENS;
  }
  if (isVerb(V.TAKE)) {
    tell("Every ", D(obj), " regards you with suspicion and won't give you a weapon.\n");
    return true;
  } else if (isVerb(V.ZAP)) {
    await PERFORM(V.ZAP, obj);
    return true;
  } else {
    return false;
  }
}

async function HUTS_F() {
  if (isVerb(V.ZAP)) {
    tell("A few huts are destroyed; many remain.\n");
    return g.ALIENS_FRIENDLY$ = false;
  } else {
    return await EX_CHECK();
  }
}

async function AS_ADVERTISED() {
  tell("The ", D(g.PRSO), " is as described.\n");
  return true;
}

async function WALL_F() {
  if ((g.HERE == FORE_END || g.HERE == FORE_END_2) && isVerb(V.CLIMB_FOO, V.CLIMB_UP, V.CLIMB_ON)) {
    tell("The wall is unscalable!\n");
    return true;
  } else {
    return false;
  }
}

async function DISTANT_BUBBLE_F() {
  if (isVerb(V.LOOK_INSIDE)) {
    tell("No details are visible.\n");
    return true;
  } else {
    return await EX_CHECK();
  }
}

async function EX_CHECK() {
  if (isVerb(V.EXAMINE)) {
    return await AS_ADVERTISED();
  } else {
    return false;
  }
}

async function VEGGIES_F() {
  if (isVerb(V.EAT)) {
    tell("Yechh!\n");
    return true;
  } else {
    return await EX_CHECK();
  }
}

async function DRIVE_CONTROLS_F() {
  if (await EX_CHECK()) {
    return true;
  } else if (isVerb(V.ZAP)) {
    return false;
  } else {
    tell("You can't do anything with them.\n");
    return true;
  }
}

async function CAGES_F() {
  return await EX_CHECK();
}

async function TOTEMS_F() {
  if (await EX_CHECK()) {
    return true;
  } else if (isVerb(V.EAT)) {
    return await VEGGIES_F();
  } else {
    tell("It would be impolite to fool with these.\n");
    return true;
  }
}

async function KNOBS_F() {
  if (isVerb(V.TAKE)) {
    tell("It is firmly attached.\n");
    return true;
  } else if (isVerb(V.REACH, V.CLIMB_UP, V.CLIMB_DOWN, V.CLIMB_FOO, V.CLIMB_ON)) {
    if (g.HERE == DRIVE_BUBBLE_ENTRANCE || g.HERE == CONTROL_BUBBLE_ENTRANCE) {
      await DO_WALK(P.UP);
    } else {
      await DO_WALK(P.DOWN);
    }
    return true;
  } else {
    return false;
  }
}

async function SWITCH_FCN() {
  if (isVerb(V.LAMP_ON, V.TURN, V.THROW)) {
    if (g.MELTED$) {
      tell("There is a sickening wheeze, but nothing else happens.\n");
      return true;
    } else if (g.SWITCH_ON$) {
      tell("It's already on.\n");
      return true;
    } else {
      tell("The lights in the room come on and there is a deafening FOOOOM! noise as the computer starts up.\n");
      g.SWITCH_ON$ = true;
      if ((loc(CARD) == SLOT) && !g.FRIED$) {
        if (g.GOT_KEY$) {
          tell("The main display blinks and displays the word \"Ready\".\n");
          return true;
        } else {
          g.GOT_KEY$ = true;
          move(GOLD_KEY, g.HERE);
          clearFlag(ENUNCIATOR, INVISIBLE);
          tell("The main display blinks twice, a bell rings, and a gold rod falls from the output hopper onto the floor! A moment later, a previously unseen enunciator panel comes on.\n");
          await PERFORM(V.EXAMINE, ENUNCIATOR);
          return true;
        }
      } else {
        tell("Lights blink on the main display and the word \"Fault\" appears.\n");
        return true;
      }
    }
  } else if (isVerb(V.LAMP_OFF)) {
    g.SWITCH_ON$ = false;
    setFlag(ENUNCIATOR, INVISIBLE);
    tell("The computer is off.\n");
    return true;
  } else {
    return false;
  }
}

async function COMPUTER_ROOM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("This is the main computer room. The builders of this ship were obviously still wedded to large mainframes: this one fills the room and is thirty meters high. There is an overlarge switch at about eye-level and an access panel below it, which is ");
    if (hasFlag(PANEL, OPENBIT)) {
      tell("open");
    } else {
      tell("closed");
    }
    tell(". The power seems to be ");
    if (g.SWITCH_ON$) {
      tell("on.\n");
    } else {
      tell("off.\n");
    }
    if (g.FRIED$) {
      tell("There is a strong smell of burning components.\n");
    }
    return true;
  } else {
    return false;
  }
}

async function ENUNCIATOR_F() {
  if (isVerb(V.EXAMINE)) {
    if (g.SWITCH_ON$) {
      tell("The panel has three banks of four colored lights: red, yellow, green, and blue. The first is labelled with a symbol of the emission of rays: of the lights underneath, the red one is flashing and the yellow one is brightly lit. The second bank is labelled with a stylized docking port and the third with an airlock. Of these two banks, the first yellow one is brightly lit and the other yellow one is flashing. The panel also contains six other lights, each bearing a stylized picture. The first four, all dark, represent navigation, engine, library, and defenses. A fifth, picturing a cage, is brightly lit. The sixth is ", S(get(g.AIR_FLASH, g.AIR_COUNT)), ". It", S(g.REPAIR_PANEL), "\n");
      return true;
    } else {
      tell("The panel is dark.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function REPAIR_ROOM_FCN(rarg) {
  if (rarg == M_LOOK) {
    tell("This room is taken up by two large pieces of machinery. The leftmost has a symbol depicting the emission of rays beside a yellow slot. The other machine", S(g.REPAIR_PANEL), " Beside it are three diagrams; under each one is a red slot. The first diagram shows four single dots equally spaced around a six-dot cluster. The second shows two eight-dot clusters in close proximity. The third has three single dots equally spaced around a seven-dot cluster. The only exit is up some stairs.\n");
    return true;
  } else {
    return false;
  }
}

async function YELLOW_SLOT_F() {
  if (isVerb(V.PUT) && (g.PRSI == YELLOW_SLOT)) {
    if (g.PRSO == YELLOW_KEY) {
      g.ALWAYS_LIT = true;
      await RIGHT_KEY();
      return crlf();
    } else if (hasFlag(g.PRSO, KEYBIT)) {
      return await WRONG_KEY();
    } else {
      return await WONT_FIT();
    }
  } else {
    return false;
  }
}

async function WONT_FIT() {
  tell("The ", D(g.PRSO), " doesn't fit in the ", D(g.PRSI), ".\n");
  return true;
}

async function RED_SLOT_F() {
  let num = 0;
  if (isVerb(V.PUT) && (g.PRSI == RED_SLOT)) {
    num = await ORDINAL(g.P_ADJECTIVE);
    if ((num > 3) || (num == 0)) {
      tell("You must specify which red slot.\n");
      return true;
    } else if (!(g.PRSO == RED_KEY)) {
      return await WRONG_KEY();
    } else {
      remove(RED_KEY);
      await RIGHT_KEY();
      tell(" You hear a subdued hum of machinery coming to life.\n");
      if (num == 2) {
        enable(await QUEUE(I_FRESH_AIR.id, 30));
        return disable(await INT(I_BAD_AIR.id));
      } else {
        enable(await QUEUE(I_POISON_AIR.id, 20));
        disable(await INT(I_BAD_AIR.id));
        if (num == 3) {
          g.AMMONIA$ = true;
        }
        return true;
      }
    }
  } else {
    return false;
  }
}

async function RIGHT_KEY() {
  remove(g.PRSO);
  tell("The ", D(g.PRSO), " disappears into the slot.");
  return true;
}

async function WRONG_KEY() {
  remove(g.PRSO);
  tell("The ", D(g.PRSO), " slides into the slot and disappears.\n");
  return true;
}

async function I_FRESH_AIR() {
  g.POISON_COUNT = 0;
  if (g.AIR_COUNT == 0) {
    return true;
  } else if ((g.AIR_COUNT = g.AIR_COUNT - 1) < 1) {
    if (!g.SUIT_ON$ && g.IN_ARTIFACT$) {
      tell("The air seems fine now.\n");
    }
    return true;
  }
  if (!g.SUIT_ON$ && g.IN_ARTIFACT$) {
    (await DESCRIBE_AIR("The air seems a bit better, but is still "));
  }
  return await QUEUE(I_FRESH_AIR.id, 20);
}

async function I_POISON_AIR() {
  if ((g.POISON_COUNT = g.POISON_COUNT + 1) > 3) {
    if (!g.IN_ARTIFACT$) {
      return enable(await QUEUE(I_POISON_AIR.id, 1));
    } else if (g.SUIT_ON$) {
      return await JIGS_UP(g.STUPID_AIRGONE_MESSAGE);
    } else {
      return (await JIGS_UP("You are overcome by noxious gases and slump to the floor, dead."));
    }
  } else {
    if (!g.SUIT_ON$ && g.IN_ARTIFACT$) {
      (await DESCRIBE_AIR("The air here has become "));
    }
    return await QUEUE(I_POISON_AIR.id, 30);
  }
}

async function I_BAD_AIR() {
  if ((g.AIR_COUNT = g.AIR_COUNT + 1) > 3) {
    g.POISON_COUNT = 4;
    if (!g.IN_ARTIFACT$) {
      return enable(await QUEUE(I_BAD_AIR.id, 1));
    } else if (!g.SUIT_ON$) {
      return (await JIGS_UP("You gasp for air, but there is none left, and slump to the floor, dead."));
    } else {
      return await JIGS_UP(g.STUPID_AIRGONE_MESSAGE);
    }
  } else {
    if (!g.SUIT_ON$ && g.IN_ARTIFACT$) {
      (await DESCRIBE_AIR("You notice that the air has become "));
    }
    return await QUEUE(I_BAD_AIR.id, 40);
  }
}

async function DESCRIBE_AIR(str) {
  if (g.POISON_COUNT == 4) {
    if (g.AIR_COUNT == 4) {
      return (await JIGS_UP("You gasp for air, but there is none left, and slump to the floor, dead."));
    } else {
      return (await JIGS_UP("You are overcome by noxious gases and slump to the floor, dead."));
    }
  } else if (g.POISON_COUNT > 0) {
    tell(S(str), S(get(g.POISON_AIRS, g.POISON_COUNT)), S(get(g.AMMONIA$ ? g.AMMONIA_TABLE : g.METHANE_TABLE, g.POISON_COUNT)), "\n");
    return true;
  } else {
    tell(S(str), S(get(g.LIGHT_AIRS, g.AIR_COUNT)), "\n");
    return true;
  }
}

